// Subflow DT session : sortie 1 = msg.dtUser (autorisé), sortie 2 = 401/403 prêt pour http response
// OUTIL vide = session seule (portail, /auth/me)
const outil = env.get('OUTIL') || '';

function refus(code, erreur, effacer) {
    msg.statusCode = code;
    msg.headers = { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' };
    msg.payload = { erreur };
    if (effacer) msg.cookies = { dt_session: { value: '', maxAge: 0, path: '/data-tools', httpOnly: true, secure: true, sameSite: 'strict' } };
    return [null, msg];
}

const P = global.get('dt_params') || {};
const gl = (P.sessionGlissanteH || 12) * 3600e3, mx = (P.sessionMaxH || 24) * 3600e3;
const jeton = ((msg.req && msg.req.cookies) || {}).dt_session;
if (typeof jeton !== 'string' || jeton.length < 20 || jeton.length > 100) return refus(401, 'non_authentifie', !!jeton);

const cle = crypto.createHash('sha256').update(jeton).digest('hex');
const S = global.get('dt_sessions') || {};
const s = S[cle];
const now = Date.now();
if (!s || now - s.vu > gl || now - s.cree > mx) {
    if (s) { delete S[cle]; global.set('dt_sessions', S); }
    return refus(401, 'non_authentifie', true);
}
if (now - s.vu > 60000) { s.vu = now; global.set('dt_sessions', S); }

if (outil && !(s.outils.includes('*') || s.outils.includes(outil))) return refus(403, 'acces_refuse');

const methode = String(msg.req.method || 'GET').toUpperCase();
if (methode !== 'GET' && methode !== 'HEAD' && msg.req.headers['x-dt'] !== '1') return refus(403, 'entete_x_dt_manquant');

msg.dtUser = { login: s.login, nom: s.nom, admin: !!s.admin, outils: [...s.outils] };
return [msg, null];

// @ts-nocheck
/* =========================================================
   T&J : collecte Business Central (M1)
   Entrées : inject nuit / deploy, demande "reload" du dashboard, réponses du nœud http request
   Sorties : 1 -> http request, 2 -> construction du modèle, 3 -> dashboard (progression)
   ========================================================= */
const C = {
  base: 'https://api.businesscentral.dynamics.com/v2.0/ef2c50ef-b9e0-499b-a90d-d7b2399d6ec4/Production/ODataV4/',
  soc: [
    { nom: 'AGRIVALOR BERGHEIM', court: 'BERGHEIM' },
    { nom: 'AGRIVALOR WITTENHEIM', court: 'WITTENHEIM' },
    { nom: 'CENTRALSACE COMPOST', court: 'CENTRALSACE' },
    { nom: 'SUNDGAU COMPOST', court: 'SUNDGAU' }
  ],
  tarifs: ['TJROUGE_2026', 'TJJAUNE_2026', 'TJBLEU_2026', 'TJVERT_2026'],
  champTarif: '',            // champ du code tarif sur Price_List_Lines_Part_Excel. Vide = détection automatique (journal), puis à renseigner
  liv: ['000131', '000132', '000133', '000318', '000396', '000755', '000797', '000802'],
  ic: ['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11', '12', '000558'],   // clients exclus : intersociété 01 à 12, et 000558
  // contrôle de complétude : écritures valeur lues dans les 9 sociétés (les 4 T&J d'abord, dans le même ordre que soc)
  toutes: ['AGRIVALOR BERGHEIM', 'AGRIVALOR WITTENHEIM', 'CENTRALSACE COMPOST', 'SUNDGAU COMPOST',
    'AGRIVALOR', 'AGRIVALOR EGUISHEIM', 'AGRIVALOR ENERGIE', 'AGRIVALOR TRANSPORT ET SERVICE', 'ECO BOIS ALSACE'],
  exclCaisse: true,          // facture rattachée à un ticket de caisse : comptée en Particulier, pas en Pro          // facture dont le No est un Document_No de caisse : comptée en Particulier, pas en Pro
  controles: [{ societe: 'SUNDGAU COMPOST', date: '2026-09-14', ht: 464.25, tickets: 14 }],
  concurrence: 8, top: 5000, timeout: 300000, relances: 4, attente: [5000, 15000, 30000, 60000], maxRun: 30 * 60000
};
const HDR = 'No,Posting_Date,Sell_to_Customer_No,Sell_to_Customer_Name,Sell_to_Post_Code,Ship_to_Post_Code,Salesperson_Code,Cancelled';
const LIN = 'Document_No,Type,No,Description,Quantity,Unit_of_Measure_Code,Amount,Line_Discount_Amount';
const E = {
  tarifs: { ent: 'Price_List_Lines_Part_Excel', sel: C.champTarif ? 'Asset_No,Description,Unit_Price,Unit_of_Measure_Code,' + C.champTarif : '', filter: C.champTarif ? C.tarifs.map(t => `${C.champTarif} eq '${t}'`).join(' or ') : '' },
  factures: { ent: 'Factures_vente_Excel', sel: HDR + ',Order_No' },
  lignesF: { ent: 'Lignes_facture_vente_Excel', sel: LIN + ',Order_No' },
  avoirs: { ent: 'Avoirs_vente_Excel', sel: HDR },
  lignesA: { ent: 'Lignes_avoir_vente_Excel', sel: LIN },
  archives: { ent: 'Archives_commandes_vente_Excel', sel: 'No,Version_No,Doc_No_Occurrence,Order_Date,Document_Date' },
  commandes: { ent: 'Commande_vente_Excel', sel: 'No,Order_Date,Document_Date,Sell_to_Customer_No,Sell_to_Customer_Name,Sell_to_Post_Code,Ship_to_Post_Code,Salesperson_Code,Status,Completely_Shipped', filter: "Document_Type eq 'Order'" },
  // activité du jour : lignes des commandes ouvertes, comptées à la date de commande, facturées ou non
  lignesCmd: { ent: 'Lignes_vente_Excel', sel: 'Document_No,Line_No,Type,No,Description,Quantity,Outstanding_Quantity,Unit_of_Measure_Code,Line_Amount', filter: "Document_Type eq 'Order'" },
  lignesPJ: { ent: 'Piece_JustificativeLines', sel: 'Receipt_No,Type,No,Description,Quantity,Unit_of_Measure_Code,Discount_Percent,Amount' },
  caisse: { ent: 'Ecritures_comptables_caisse', sel: 'Posting_Date,Posting_Date_Time,Document_No,Receipt_No,Customer_No,Customer_Name,Entry_Type,Amount,Cash_Register_Code,Salesperson_Code,Payment_Method_Code' },
  // contrôle de complétude : toutes les ventes d'articles validées (factures, avoirs, caisse), dans les 9 sociétés.
  // optionnel : un échec n'empêche pas la mise à jour du dashboard, il est signalé dans l'onglet Contrôle.
  valeurs: { ent: 'ValueEntries', sel: 'Entry_No,Item_No,Item_Ledger_Entry_Type,Posting_Date,Document_Type,Document_No,Sales_Amount_Actual,Invoiced_Quantity', filter: "Item_Ledger_Entry_Type eq 'Sale'", toutes: true, optionnel: true }
};
// sociétés lues pour une entité : les 9 pour le contrôle, sinon les 4 sociétés T&J
const societesDe = k => (E[k].toutes ? C.toutes : C.soc.map(s => s.nom));
const RUN = 'tj_run';

function jobUrl(j) {
  const e = E[j.key], q = [];
  if (e.sel && !j.noSel) q.push('$select=' + e.sel);
  if (e.filter) q.push('$filter=' + encodeURIComponent(e.filter));
  q.push('$top=' + C.top);
  if (j.skip) q.push('$skip=' + j.skip);
  return C.base + "Company('" + encodeURIComponent(societesDe(j.key)[j.pf]) + "')/" + e.ent + '?' + q.join('&');
}
function auth() {
  let t = global.get('TokenBC');
  if (t && typeof t === 'object') t = t.access_token || t.token || '';
  t = String(t || '');
  return /^bearer /i.test(t) ? t : 'Bearer ' + t;
}
function toHttp(j, R) {
  return {
    url: j.url || jobUrl(j), requestTimeout: C.timeout,
    headers: { Authorization: auth(), Accept: 'application/json', 'Data-Access-Intent': 'ReadOnly' },
    tj: { run: R.id, job: j }
  };
}
function pump(R) {
  const out = [];
  while (R.active < C.concurrence && R.queue.length) { R.active++; out.push(toHttp(R.queue.shift(), R)); }
  return out.length ? out : null;
}
const nbRows = R => { let n = 0; for (const k in R.stats) for (const v of R.stats[k]) n += v; return n; };
function prog(R, txt, force) {
  const now = Date.now();
  if (!force && now - (R.lastProg || 0) < 400) return null;
  R.lastProg = now;
  const pct = R.total ? Math.min(95, Math.round((R.done / R.total) * 95)) : 0;
  return { payload: { type: 'progress', on: true, pct, text: txt || `Collecte BC : ${R.done}/${R.total} requêtes, ${nbRows(R).toLocaleString('fr-FR')} lignes` } };
}
function errTxt(m) {
  const p = m.payload;
  if (p && typeof p === 'object' && p.error) return `${m.statusCode} ${p.error.code || ''} ${p.error.message || ''}`.trim();
  return `${m.statusCode || '?'} ${String(p || '').slice(0, 300)}`;
}

function start(origine) {
  const R0 = flow.get(RUN);
  if (R0 && !R0.fini && Date.now() - R0.t0 < C.maxRun) {
    node.warn('T&J : chargement déjà en cours, demande ignorée');
    return [null, null, prog(R0, null, true)];
  }
  if (!global.get('TokenBC')) {
    node.error('T&J : global TokenBC absent, chargement annulé');
    node.status({ fill: 'red', shape: 'ring', text: 'TokenBC absent' });
    return [null, null, { payload: { type: 'progress', on: false, pct: 0, text: 'TokenBC absent : chargement annulé', err: true } }];
  }
  const R = { id: Date.now().toString(36), t0: Date.now(), origine, queue: [], active: 0, done: 0, total: 0, pages: 0, raw: {}, stats: {}, errors: [], alerts: [], fini: false, lastProg: 0 };
  for (const k in E) { R.raw[k] = societesDe(k).map(() => []); R.stats[k] = societesDe(k).map(() => 0); }
  // les grosses entités d'abord pour lisser la fin de collecte
  const ordre = ['valeurs', 'lignesF', 'lignesCmd', 'caisse', 'lignesPJ', 'factures', 'archives', 'lignesA', 'avoirs', 'commandes', 'tarifs'].filter(k => E[k]);
  for (const k of ordre) societesDe(k).forEach((s, pf) => R.queue.push({ key: k, pf, page: 1, try: 0, skip: 0 }));
  R.total = R.queue.length;
  flow.set(RUN, R);
  node.status({ fill: 'blue', shape: 'dot', text: `collecte 0/${R.total} (${origine})` });
  return [pump(R), null, prog(R, `Collecte BC : 0/${R.total} requêtes`, true)];
}

function finish(R, out1) {
  R.fini = true;
  const ms = Date.now() - R.t0;
  const payload = { raw: R.raw, C, E, stats: R.stats, errors: R.errors, alerts: R.alerts, manquants: R.manquants || [], ms, pages: R.pages, origine: R.origine, runId: R.id };
  flow.set(RUN, { id: R.id, t0: R.t0, fini: true, ms, done: R.done, total: R.total, errors: R.errors.length });
  node.status({ fill: R.errors.length ? 'yellow' : 'green', shape: 'dot', text: `${R.pages} pages, ${nbRows(R)} lignes, ${Math.round(ms / 1000)} s${R.errors.length ? ', ' + R.errors.length + ' erreurs' : ''}` });
  return [out1, { payload }, prog(R, 'Construction du modèle en mémoire', true)];
}
function fin(R) {
  R.active--; R.done++;
  const out1 = pump(R);
  flow.set(RUN, R);
  if (!R.active && !R.queue.length) return finish(R, out1);
  if (R.done % 5 === 0) node.status({ fill: 'blue', shape: 'dot', text: `collecte ${R.done}/${R.total}` });
  return [out1, null, prog(R)];
}

function onResp() {
  const R = flow.get(RUN);
  if (!R || R.fini || msg.tj.run !== R.id) return null;           // réponse d'un chargement obsolète
  const j = msg.tj.job, sc = Number(msg.statusCode), pl = msg.payload;
  const lib = `${E[j.key].ent} / ${societesDe(j.key)[j.pf]} page ${j.page}`;
  if (sc >= 200 && sc < 300 && pl && typeof pl === 'object' && Array.isArray(pl.value)) {
    const dst = R.raw[j.key][j.pf];
    for (const r of pl.value) dst.push(r);
    R.stats[j.key][j.pf] += pl.value.length; R.pages++;
    const nx = pl['@odata.nextLink'];
    if (nx) { R.queue.unshift(Object.assign({}, j, { url: nx, page: j.page + 1, try: 0, mode: 'next' })); R.total++; }
    else if (j.mode !== 'next' && pl.value.length >= C.top) { R.queue.unshift(Object.assign({}, j, { url: null, skip: (j.skip || 0) + C.top, page: j.page + 1, try: 0 })); R.total++; }
    return fin(R);
  }
  const err = errTxt(msg);
  // champ du $select inconnu de BC : une seule relance sans $select, signalée au journal
  if (sc === 400 && E[j.key].sel && !j.noSel && !j.url && /select|propert|propri/i.test(err)) {
    j.noSel = true; R.alerts.push(`${lib} : $select refusé par BC (${err}), relancé sans $select. Un champ du brief n'existe pas sur cette entité.`);
    flow.set(RUN, R);
    return [[toHttp(j, R)], null, null];
  }
  if (![400, 403, 404].includes(sc) && j.try < C.relances) {
    j.try++;
    let w = C.attente[Math.min(j.try - 1, C.attente.length - 1)];
    const ra = msg.headers && Number(msg.headers['retry-after']);
    if (ra > 0) w = Math.max(w, ra * 1000);
    node.status({ fill: 'yellow', shape: 'ring', text: `relance ${j.try}/${C.relances} dans ${w / 1000} s : ${lib}` });
    const id = R.id;
    setTimeout(() => {
      const R2 = flow.get(RUN);
      if (!R2 || R2.id !== id || R2.fini) return;
      node.send([toHttp(j, R2), null, null]);
    }, w);
    return null;
  }
  // entité de contrôle : l'échec est signalé sans bloquer la mise à jour du dashboard
  if (E[j.key].optionnel) {
    R.alerts.push(`${lib} : ${err}${j.try ? ` (après ${j.try} relances)` : ''} : contrôle de complétude incomplet`);
    R.manquants = (R.manquants || []).concat(j.key + '|' + j.pf);
    return fin(R);
  }
  R.errors.push(`${lib} : ${err}${j.try ? ` (après ${j.try} relances)` : ''}`);
  return fin(R);
}

if (msg.tj) return onResp();
return start(msg.topic || 'manuel');

initialize:
// Redeploy pendant une collecte : les minuteries sont perdues, on libère le verrou
const R = flow.get('tj_run');
if (R && !R.fini) flow.set('tj_run', { id: 'reset', fini: true });

