// @ts-nocheck
/* =========================================================
   T&J : construction du modèle en mémoire (fonction pure)
   buildModel(raw, C) -> { M, J }
   raw : { cle_entite: [lignesSociete0, lignesSociete1, ...] }
   ========================================================= */
function buildModel(raw, C) {
  const t0 = Date.now();
  const J = { rejets: {}, ignores: {}, dedup: [], remplissage: [], controles: [], totaux: [], alertes: [] };
  const rej = (m, n = 1) => { if (n) J.rejets[m] = (J.rejets[m] || 0) + n; };
  const ign = (m, n = 1) => { if (n) J.ignores[m] = (J.ignores[m] || 0) + n; };
  const S = x => (x === null || x === undefined ? '' : String(x).trim());
  const N = x => { const n = Number(x); return isFinite(n) ? n : 0; };
  const D = x => { const s = S(x).slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(s) && s > '1900-01-01' ? s : ''; };
  const blank = t => { const s = S(t); return !s || s === '_x0020_'; };
  const r2 = x => Math.round((x + (x >= 0 ? 1e-9 : -1e-9)) * 100) / 100;
  const pc = (a, b) => (b ? Math.round((a / b) * 1000) / 10 : 0);
  const npf = C.soc.length;
  const LIV = new Set(C.liv.map(S));
  const fmtP = new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const paris = iso => {
    let s = S(iso); if (!s || s < '1900') return null;
    if (!/[zZ]|[+-]\d\d:?\d\d$/.test(s)) s += 'Z';
    const d = new Date(s); if (isNaN(d)) return null;
    const p = {}; for (const x of fmtP.formatToParts(d)) p[x.type] = x.value;
    return { d: `${p.year}-${p.month}-${p.day}`, h: Number(p.hour) % 24 };
  };
  const dowOf = s => (new Date(s + 'T00:00:00Z').getUTCDay() + 6) % 7;
  const jourParis = (() => { const o = {}; for (const x of new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date())) o[x.type] = x.value; return `${o.year}-${o.month}-${o.day}`; })();
  const ilYA = n => new Date(Date.parse(jourParis + 'T00:00:00Z') - n * 864e5).toISOString().slice(0, 10);
  for (const k of Object.keys(raw)) for (let pf = 0; pf < npf; pf++) if (!raw[k][pf]) raw[k][pf] = [];

  /* 1. Doublons inter-sociétés : enregistrement strictement identique renvoyé par plusieurs sociétés */
  for (const k of Object.keys(raw)) {
    const seen = new Map(); const info = { entite: k, retires: 0, detail: [] };
    for (let pf = 0; pf < npf; pf++) {
      const rows = raw[k][pf]; const keep = []; let dup = 0; const of = {};
      for (const r of rows) {
        delete r['@odata.etag'];
        const sig = JSON.stringify(r); const p = seen.get(sig);
        if (p !== undefined && p !== pf) { dup++; of[p] = 1; continue; }
        if (p === undefined) seen.set(sig, pf);
        keep.push(r);
      }
      raw[k][pf] = keep;
      if (dup) { info.retires += dup; info.detail.push(`${C.soc[pf].nom} : ${dup}/${rows.length} identiques à ${Object.keys(of).map(i => C.soc[i].nom).join(', ')}`); }
    }
    if (info.retires) J.dedup.push(info);
  }

  /* 2. Tarifs T&J */
  const tarifs = {}; let sansChamp = 0;
  raw.tarifs.forEach(rows => rows.forEach(r => {
    const art = S(r.Asset_No); if (!art) { rej('tarif : ligne sans Asset_No'); return; }
    const tf = S(r[C.champTarif]) || '?'; if (tf === '?') sansChamp++;
    const u = S(r.Unit_of_Measure_Code);
    const T = tarifs[art] || (tarifs[art] = { lib: S(r.Description), p: {} });
    const pt = T.p[tf] || (T.p[tf] = {});
    pt[u] = Math.max(pt[u] || 0, N(r.Unit_Price));
  }));
  const tj = new Set(Object.keys(tarifs));
  if (sansChamp) J.alertes.push(`Champ ${C.champTarif} absent sur ${sansChamp} lignes de tarif : prix tarif non attribuables`);
  if (!tj.size) J.alertes.push('AUCUN article T&J chargé : le périmètre Pro sera vide');
  const artLib = {}; for (const a in tarifs) artLib[a] = tarifs[a].lib;
  const livLib = {};

  /* 3. Commandes ouvertes et archives */
  const cmd = {}; const noms = {};
  raw.commandes.forEach((rows, pf) => rows.forEach(r => {
    const no = S(r.No); if (!no) return;
    const cli = S(r.Sell_to_Customer_No);
    cmd[pf + '|' + no] = { d: D(r.Order_Date) || D(r.Document_Date), cli, cp: S(r.Ship_to_Post_Code) || S(r.Sell_to_Post_Code), vend: S(r.Salesperson_Code) };
    if (cli && !noms[cli]) noms[cli] = S(r.Sell_to_Customer_Name);
  }));
  const arch = {};
  raw.archives.forEach((rows, pf) => rows.forEach(r => {
    const k = pf + '|' + S(r.No); const v = N(r.Version_No), o = N(r.Doc_No_Occurrence);
    const d = D(r.Order_Date) || D(r.Document_Date); if (!d) return;
    const c = arch[k];
    if (!c || o > c.o || (o === c.o && v < c.v)) arch[k] = { v, o, d };
  }));
  // intersociété : uniquement les clients du paramètre ic (codes 01 à 12)
  const IC = new Set(C.ic.map(S));

  /* 4. Caisse (Particulier) */
  const tk = {}; const cashIdx = new Map(), cashRec = new Map(); let avecHeure = 0, nbSales = 0;
  raw.caisse.forEach((rows, pf) => rows.forEach(r => {
    const ty = S(r.Entry_Type).toLowerCase(); const rec = S(r.Receipt_No);
    if (ty === 'opening' || ty === 'closing') { ign('caisse ' + ty); return; }
    if (ty === 'refund') { ign('caisse refund (rendu monnaie)'); return; }
    if (ty !== 'sales' && ty !== 'payment') { rej('caisse Entry_Type inconnu : ' + S(r.Entry_Type)); return; }
    if (!rec) { rej('caisse ' + ty + ' sans Receipt_No'); return; }
    const key = pf + '|' + rec;
    const t = tk[key] || (tk[key] = { pf, rec, d: '', h: null, dow: 0, caisse: '', vend: '', cli: '', ht: 0, pay: {}, ns: 0, tm: '' });
    if (ty === 'sales') {
      nbSales++; t.ns++; t.ht += N(r.Amount);
      const d = D(r.Posting_Date); if (d && (!t.d || d < t.d)) t.d = d;
      const tm = S(r.Posting_Date_Time);
      if (tm && tm > '1900' && (!t.tm || tm < t.tm)) t.tm = tm;
      if (!t.caisse) t.caisse = S(r.Cash_Register_Code);
      if (!t.vend) t.vend = S(r.Salesperson_Code);
      if (!t.cli) { t.cli = S(r.Customer_No); if (t.cli && !noms[t.cli]) noms[t.cli] = S(r.Customer_Name); }
      const dn = S(r.Document_No); if (dn) { const kd = pf + '|' + dn, v = cashIdx.get(kd); cashIdx.set(kd, v === undefined || v === key ? key : ''); }
      cashRec.set(key, key);
    } else {
      const m = S(r.Payment_Method_Code) || 'Non renseigné';
      t.pay[m] = (t.pay[m] || 0) + Math.abs(N(r.Amount));
    }
  }));
  const tickets = []; const tkOk = new Map(); let avecPay = 0, avecCli = 0;
  for (const k in tk) {
    const t = tk[k];
    if (!t.ns) { rej('ticket sans écriture Sales'); continue; }
    const p = t.tm ? paris(t.tm) : null;
    if (p) { avecHeure++; t.h = p.h; if (!t.d) t.d = p.d; }
    if (!t.d) { rej('ticket sans date'); continue; }
    t.dow = dowOf(t.d); t.ht = r2(t.ht); t.ic = !!t.cli && IC.has(t.cli);
    const tot = Object.values(t.pay).reduce((a, b) => a + b, 0);
    t.pm = {}; if (tot > 0) { avecPay++; for (const m in t.pay) t.pm[m] = t.pay[m] / tot; } else t.pm['Non renseigné'] = 1;
    if (t.cli) avecCli++;
    delete t.pay; delete t.ns; delete t.tm;
    tickets.push(t); tkOk.set(k, t);
  }
  tickets.sort((a, b) => (a.d < b.d ? -1 : a.d > b.d ? 1 : 0));

  /* 5. Factures et avoirs (Pro) */
  const docs = {}; const facts = [];
  const src = { archive: 0, ouverte: 0, repli: 0, sansOrderNo: 0 };
  const orderDate = (pf, ord) => {
    const a = arch[pf + '|' + ord]; if (a) { src.archive++; return a.d; }
    const o = cmd[pf + '|' + ord]; if (o && o.d) { src.ouverte++; return o.d; }
    src.repli++; return '';
  };
  /* Détail article du comptoir : lignes des documents BC rattachés à la caisse (Document_No, sinon Receipt_No) */
  const cpt = [], cptDocs = new Set(), cptSrc = { piece: 0, facture: 0, avoir: 0, parDoc: 0, parRec: 0, multi: 0 };
  const cashKey = k => {
    if (cashIdx.has(k)) { cptSrc.parDoc++; return cashIdx.get(k); }
    if (cashRec.has(k)) { cptSrc.parRec++; return cashRec.get(k); }
    return undefined;
  };
  const tkDet = new Set();
  function addCpt(sg, pf, docNo, dDoc, tkKey, rows, get) {
    const t = tkKey ? tkOk.get(tkKey) : null; let n = 0;
    if (!t) { cptSrc.multi++; ign('document de caisse couvrant plusieurs tickets (non rattaché)', rows.length); return 0; }
    tkDet.add(tkKey);
    for (const r of rows) {
      const x = get(r); if (!x || !x.art) continue;
      if (!tj.has(x.art) && !LIV.has(x.art)) { ign('ligne de ticket hors T&J'); continue; }
      cpt.push({ t: 'T', pf, doc: docNo, tk: t ? tkKey : '', d: t ? t.d : dDoc, art: x.art, u: x.u, q: sg * x.q, ht: sg * x.ht, brut: sg * (x.ht + x.rem), rem: sg * x.rem, liv: LIV.has(x.art), tj: tj.has(x.art), cli: t ? t.cli : '', ic: t ? t.ic : false });
      if (!artLib[x.art] && x.lib) artLib[x.art] = x.lib;
      n++;
    }
    if (n) cptDocs.add(pf + '|' + docNo);
    return n;
  }
  const ligneBC = r => (blank(r.Type) ? null : { art: S(r.No), u: S(r.Unit_of_Measure_Code), q: N(r.Quantity), ht: N(r.Amount), rem: N(r.Line_Discount_Amount), lib: S(r.Description) });
  /* Source principale : lignes des pièces justificatives de caisse (Piece_JustificativeLines.Receipt_No = Receipt_No du ticket) */
  const tkPJ = new Set(), pjAutres = new Set(); let pjHors = 0;
  (raw.lignesPJ || []).forEach((rows, pf) => {
    const G = {};
    for (const r of rows) { const rn = S(r.Receipt_No); if (rn) (G[rn] || (G[rn] = [])).push(r); }
    for (const rn in G) {
      const kt = pf + '|' + rn;
      if (!tkOk.has(kt)) { pjHors += G[rn].length; pjAutres.add(kt); continue; }  // facture émise depuis un ticket (CRF), etc.
      cptSrc.piece++; tkPJ.add(kt);
      addCpt(1, pf, rn, '', kt, G[rn], r => {
        if (blank(r.Type)) return null;
        const ht = N(r.Amount), p = N(r.Discount_Percent), brut = p > 0 && p < 100 ? ht / (1 - p / 100) : ht;
        return { art: S(r.No), u: S(r.Unit_of_Measure_Code), q: N(r.Quantity), ht, rem: brut - ht, lib: S(r.Description) };
      });
    }
  });
  ign('ligne de pièce justificative sans ticket caisse (facture émise depuis un ticket, etc.)', pjHors);
  // documents écartés et lignes hors articles T&J, gardés pour le contrôle de complétude
  const exclus = {}, hors = {}, horsArt = {};
  // lignes facturées des commandes encore ouvertes : la commande est comptée en entier sur ses propres lignes
  const factCmd = {};
  // commandes ouvertes effectivement comptées sur leurs lignes (au moins un article T&J et une date)
  const cmdComptees = new Set();
  (raw.lignesCmd || []).forEach((rows, pf) => rows.forEach(r => {
    const k = pf + '|' + S(r.Document_No);
    if (cmd[k] && cmd[k].d && !blank(r.Type) && tj.has(S(r.No))) cmdComptees.add(k);
  }));
  function traiter(kind, hdr, lines) {
    const H = {};
    hdr.forEach((rows, pf) => rows.forEach(r => { H[pf + '|' + S(r.No)] = r; }));
    const G = {};
    lines.forEach((rows, pf) => rows.forEach(r => { const k = pf + '|' + S(r.Document_No); (G[k] || (G[k] = { pf, rows: [] })).rows.push(r); }));
    const lib = kind === 'F' ? 'facture' : 'avoir'; const sg = kind === 'F' ? 1 : -1;
    for (const key in G) {
      const { pf, rows } = G[key]; const h = H[key];
      if (!h) { rej(lib + ' : entête introuvable', rows.length); exclus[key] = 'Entête introuvable (collecte incomplète ?)'; continue; }
      if (pjAutres.has(key)) { rej(lib + ' émise depuis un ticket de caisse (déjà en Particulier)', rows.length); exclus[key] = 'Émise depuis un ticket de caisse : déjà comptée en Particulier'; continue; }
      const ck = C.exclCaisse ? cashKey(key) : undefined;
      if (ck !== undefined) {
        cptSrc[kind === 'F' ? 'facture' : 'avoir']++;
        if (!tkPJ.has(ck)) ign(lib + ' de caisse : lignes rattachées au comptoir (hors Pro)', addCpt(sg, pf, S(h.No), D(h.Posting_Date), ck, rows, ligneBC));
        continue;
      }
      if (!rows.some(r => !blank(r.Type) && tj.has(S(r.No)))) { rej(lib + ' non T&J (aucun code des tarifs)', rows.length); exclus[key] = 'Aucun article des tarifs T&J'; continue; }
      const dF = D(h.Posting_Date); if (!dF) { rej(lib + ' sans Posting_Date', rows.length); exclus[key] = 'Sans date de comptabilisation'; continue; }
      const no = S(h.No), cli = S(h.Sell_to_Customer_No);
      if (cli && !noms[cli]) noms[cli] = S(h.Sell_to_Customer_Name);
      const doc = docs[kind + '|' + pf + '|' + no] = {
        t: kind, pf, no, cli, dF, cp: S(h.Ship_to_Post_Code) || S(h.Sell_to_Post_Code), vend: S(h.Salesperson_Code),
        annule: h.Cancelled === true, liv: false, arts: [], ic: !!cli && IC.has(cli)
      };
      const ic = doc.ic;
      for (const r of rows) {
        if (blank(r.Type)) { ign('ligne commentaire (Type vide)'); continue; }
        const art = S(r.No); const liv = LIV.has(art);
        if (!liv && !tj.has(art)) {
          ign('ligne hors T&J dans un document T&J');
          const kh = pf + '|' + S(r.Type);
          const x = hors[kh] || (hors[kh] = { pf, type: S(r.Type) === 'Item' ? 'Article hors tarifs T&J' : S(r.Type), lignes: 0, ht: 0 });
          x.lignes++; x.ht += sg * N(r.Amount);
          if (S(r.Type) === 'Item') {
            const xa = horsArt[art] || (horsArt[art] = { art, lib: S(r.Description), lignes: 0, ht: 0, pfs: {} });
            xa.lignes++; xa.ht += sg * N(r.Amount); xa.pfs[pf] = true;
          }
          continue;
        }
        const ht = N(r.Amount), rem = N(r.Line_Discount_Amount), q = N(r.Quantity);
        let dC = dF, dCs = kind === 'A' ? 2 : 0; const ord = kind === 'F' ? S(r.Order_No) : '';
        if (ord && cmdComptees.has(pf + '|' + ord)) {
          const fc = factCmd[key] || (factCmd[key] = { pf, d: dF, ht: 0, ic });
          fc.ht += ht;
          continue;
        }
        if (kind === 'F') { if (ord) { const od = orderDate(pf, ord); if (od) { dC = od; dCs = 1; } } else src.sansOrderNo++; }
        facts.push({ t: kind, pf, doc: no, vente: ord || no, dF, dC, dCs, cli, cp: doc.cp, art, u: S(r.Unit_of_Measure_Code), q: sg * q, ht: sg * ht, brut: sg * (ht + rem), rem: sg * rem, liv, ic, vend: doc.vend, ord });
        if (!artLib[art]) artLib[art] = S(r.Description);
        if (liv) { doc.liv = true; if (!livLib[art]) livLib[art] = S(r.Description); } else if (!doc.arts.includes(art)) doc.arts.push(art);
      }
    }
  }
  traiter('F', raw.factures, raw.lignesF);
  traiter('A', raw.avoirs, raw.lignesA);

  /* 5 bis. Activité du jour : commandes encore ouvertes, comptées en entier à leur date de commande,
     livrées ou non, facturées ou non. Leurs lignes de facture ont été écartées plus haut. */
  let nbCmdOuvertes = 0;
  const cmdAnciennes = [];
  {
    const G = {};
    (raw.lignesCmd || []).forEach((rows, pf) => rows.forEach(r => {
      const k = pf + '|' + S(r.Document_No);
      (G[k] || (G[k] = { pf, no: S(r.Document_No), rows: [] })).rows.push(r);
    }));
    for (const k in G) {
      const { pf, no, rows } = G[k];
      const o = cmd[k];
      if (!o) { rej('ligne de commande sans entête', rows.length); continue; }
      if (!rows.some(r => !blank(r.Type) && tj.has(S(r.No)))) { ign('commande ouverte non T&J', rows.length); continue; }
      if (!o.d) { rej('commande ouverte sans date', rows.length); continue; }
      const ic = !!o.cli && IC.has(o.cli);
      docs['F|' + pf + '|' + no] = { t: 'F', pf, no, cli: o.cli, dF: o.d, cp: o.cp, vend: o.vend, annule: false, liv: false, arts: [], ic, enCours: true };
      for (const r of rows) {
        if (blank(r.Type)) continue;
        const art = S(r.No), liv = LIV.has(art);
        if (!liv && !tj.has(art)) { ign('ligne hors T&J dans une commande T&J'); continue; }
        const ht = N(r.Line_Amount);
        facts.push({ t: 'F', pf, doc: no, vente: no, dF: o.d, dC: o.d, dCs: 1, cli: o.cli, cp: o.cp, art, u: S(r.Unit_of_Measure_Code), q: N(r.Quantity), ht, brut: ht, rem: 0, liv, ic, vend: o.vend, ord: no, cmd: true });
        if (!artLib[art]) artLib[art] = S(r.Description);
        if (liv && !livLib[art]) livLib[art] = S(r.Description);
      }
      nbCmdOuvertes++;
      if (o.d < ilYA(60) && !ic) {
        const ht = rows.filter(r => !blank(r.Type) && (tj.has(S(r.No)) || LIV.has(S(r.No)))).reduce((s, r) => s + N(r.Line_Amount), 0);
        cmdAnciennes.push({ pf, no, d: o.d, cli: o.cli, ht: r2(ht), age: Math.round((Date.parse(jourParis) - Date.parse(o.d)) / 864e5) });
      }
    }
  }

  cpt.sort((a, b) => (a.d < b.d ? -1 : a.d > b.d ? 1 : 0));

  /* Particulier = tickets contenant au moins un article T&J ; CA HT = leurs lignes T&J et livraison (écritures caisse = TTC, tous produits) */
  const htTk = {}, tjTk = new Set();
  for (const l of cpt) { htTk[l.tk] = (htTk[l.tk] || 0) + l.ht; if (l.tj) tjTk.add(l.tk); }
  const nTk0 = tickets.length, keepTk = [], tkSansDet = new Set(); let horsTJ = 0, sansDet = 0, ttcSansDet = 0;
  for (const t of tickets) {
    const k = t.pf + '|' + t.rec;
    if (tjTk.has(k)) { t.ttc = t.ht; t.ht = r2(htTk[k]); keepTk.push(t); }
    else if (tkDet.has(k)) horsTJ++;
    else { sansDet++; ttcSansDet += t.ht; tkSansDet.add(k); }
  }
  tickets.length = 0; for (const t of keepTk) tickets.push(t);
  const keepL = cpt.filter(l => tjTk.has(l.tk)); cpt.length = 0; for (const l of keepL) cpt.push(l);
  J.remplissage.push(`Particulier T&J : ${tickets.length} tickets retenus sur ${nTk0} ; exclus : ${horsTJ} sans article T&J, ${sansDet} sans détail article (${r2(ttcSansDet)} € TTC) ; CA HT = lignes T&J et livraison des tickets retenus ; sources : ${cptSrc.piece} pièces justificatives, ${cptSrc.facture} factures, ${cptSrc.avoir} avoirs`);
  if (sansDet > nTk0 * 0.05) J.alertes.push(`${sansDet} tickets caisse sans détail article (> 5 %) : exclus du CA Particulier`);

  /* 7 bis. Ventes reprises des écritures valeur : documents BC validés avec des articles T&J
     qu'aucune autre source n'a donnés (avoir de caisse, ticket sans détail, lignes manquantes...) */
  const toutesSoc = C.toutes || C.soc.map(s => s.nom);
  const avecMontant = t => !/shipment|receipt/i.test(t);      // les montants réels sont sur factures et avoirs
  const cliDoc = {}, cmdDoc = {}, docTk = {}, tkDoc = {};
  (raw.factures || []).forEach((rows, pf) => rows.forEach(r => { const k = pf + '|' + S(r.No); cliDoc[k] = S(r.Sell_to_Customer_No); cmdDoc[k] = S(r.Order_No); }));
  (raw.avoirs || []).forEach((rows, pf) => rows.forEach(r => { cliDoc[pf + '|' + S(r.No)] = S(r.Sell_to_Customer_No); }));
  (raw.caisse || []).forEach((rows, pf) => rows.forEach(r => {
    const rec = S(r.Receipt_No), dn = S(r.Document_No);
    if (!rec || !dn) return;
    const kd = pf + '|' + dn, kt = pf + '|' + rec;
    if (!docTk[kt]) docTk[kt] = kd;
    (tkDoc[kd] || (tkDoc[kd] = new Set())).add(kt);
    if (!cliDoc[kd] && S(r.Customer_No)) cliDoc[kd] = S(r.Customer_No);
  }));
  // écritures valeur des articles T&J et livraison, regroupées par document
  const B = {};
  for (let pf = 0; pf < toutesSoc.length; pf++) {
    for (const r of (raw.valeurs && raw.valeurs[pf]) || []) {
      const art = S(r.Item_No);
      if (!tj.has(art) && !LIV.has(art)) continue;
      if (!avecMontant(S(r.Document_Type))) continue;
      const k = pf + '|' + S(r.Document_No);
      const b = B[k] || (B[k] = { pf, doc: S(r.Document_No), type: S(r.Document_Type), d: '', ht: 0, tj: false, lignes: [] });
      const ht = N(r.Sales_Amount_Actual);
      b.ht += ht;
      if (tj.has(art)) b.tj = true;
      const d = D(r.Posting_Date);
      if (d && (!b.d || d < b.d)) b.d = d;
      b.lignes.push({ art, q: -N(r.Invoiced_Quantity), ht });
    }
  }
  // document BC d'une ligne de comptoir : document de caisse du ticket, sinon ticket ou document lui-même
  const cleCaisse = l => { const cands = [docTk[l.tk], l.tk, l.pf + '|' + l.doc].filter(Boolean); return cands.find(x => B[x]) || cands[0]; };
  // documents du modèle (partie facturée) : lignes rattachées à chaque document BC
  const parDoc = {};
  const rattacher = (k, pf, d, ligne, canal) => {
    const m = parDoc[k] || (parDoc[k] = { pf, d, ht: 0, canal, facts: [], cpt: [] });
    m.ht += ligne.ht;
    if (d && (!m.d || d < m.d)) m.d = d;
    (canal === 'Pro' ? m.facts : m.cpt).push(ligne);
  };
  for (const f of facts) if (!f.cmd) rattacher(f.pf + '|' + f.doc, f.pf, f.dF, f, 'Pro');
  for (const l of cpt) rattacher(cleCaisse(l), l.pf, l.d, l, 'Particulier');
  const presents = new Set(Object.keys(parDoc));
  for (const k in factCmd) presents.add(k);

  // tickets validés dans BC sous un autre numéro (même société, même jour, même montant)
  const alias = {}, apparies = [];
  const libres = {};
  for (const k in parDoc) {
    const m = parDoc[k];
    if (B[k] || m.canal !== 'Particulier' || !m.d) continue;
    const kk = m.pf + '|' + m.d + '|' + Math.round(m.ht * 100);
    (libres[kk] || (libres[kk] = [])).push(k);
  }
  const reprendre = [];
  for (const k in B) {
    const b = B[k];
    if (b.pf >= npf || !b.tj || !b.d || Math.abs(b.ht) <= 0.01) continue;
    if (presents.has(k) || exclus[k]) continue;
    const cli = cliDoc[k] || '';
    if (cli && IC.has(cli)) continue;                                  // intersociété ou client exclu
    if (cmdDoc[k] && cmdComptees.has(b.pf + '|' + cmdDoc[k])) continue;   // facture d'une commande ouverte : déjà comptée
    const caisse = !!tkDoc[k] || /^CAIS|^CS-/i.test(b.doc);
    const kk = b.pf + '|' + b.d + '|' + Math.round(b.ht * 100);
    if (caisse && libres[kk] && libres[kk].length) {
      const km = libres[kk].shift();
      alias[km] = k;
      apparies.push({ pf: b.pf, d: b.d, ticket: km.slice(km.indexOf('|') + 1), doc: b.doc, ht: r2(b.ht) });
      continue;
    }
    reprendre.push({ k, b, cli, caisse });
  }

  // montants légèrement différents de BC (remise ou frais répartis) : alignés sur les écritures valeur
  const ajustes = [];
  for (const km in parDoc) {
    const k = alias[km] || km;
    const b = B[k], m = parDoc[km];
    if (!b || b.pf >= npf || !m.ht) continue;
    const ecart = b.ht - m.ht;
    if (Math.abs(ecart) <= 0.01) continue;
    if (Math.abs(ecart) > Math.max(20, Math.abs(b.ht) * 0.1)) continue;   // écart important : laissé visible dans le contrôle
    const f = b.ht / m.ht;
    for (const l of m.facts.concat(m.cpt)) { l.ht *= f; l.brut *= f; l.rem *= f; }
    ajustes.push({ pf: m.pf, doc: b.doc, d: b.d, avant: r2(m.ht), apres: r2(b.ht), ecart: r2(ecart) });
    m.ht = b.ht;
  }
  if (ajustes.length) {
    // montant des tickets = somme de leurs lignes
    const htTk2 = {};
    for (const l of cpt) htTk2[l.tk] = (htTk2[l.tk] || 0) + l.ht;
    for (const t of tickets) { const kt = t.pf + '|' + t.rec; if (htTk2[kt] !== undefined) t.ht = r2(htTk2[kt]); }
  }

  const repris = [];
  for (const { k, b, cli, caisse } of reprendre) {
    if (caisse) {
      tickets.push({ pf: b.pf, rec: b.doc, d: b.d, h: null, dow: dowOf(b.d), caisse: '', vend: '', cli, ht: r2(b.ht), ic: false, pm: { 'Non renseigné': 1 }, repris: true });
      for (const x of b.lignes) cpt.push({ t: 'T', pf: b.pf, doc: b.doc, tk: b.pf + '|' + b.doc, d: b.d, art: x.art, u: '', q: x.q, ht: x.ht, brut: x.ht, rem: 0, liv: LIV.has(x.art), tj: tj.has(x.art), cli, ic: false, repris: true });
    } else {
      const t = b.ht < 0 ? 'A' : 'F';
      docs[t + '|' + b.pf + '|' + b.doc] = { t, pf: b.pf, no: b.doc, cli, dF: b.d, cp: '', vend: '', annule: false, liv: false, arts: [], ic: false, repris: true };
      for (const x of b.lignes) facts.push({ t, pf: b.pf, doc: b.doc, vente: b.doc, dF: b.d, dC: b.d, dCs: 0, cli, cp: '', art: x.art, u: '', q: x.q, ht: x.ht, brut: x.ht, rem: 0, liv: LIV.has(x.art), ic: false, vend: '', ord: '', repris: true });
    }
    repris.push({ pf: b.pf, doc: b.doc, type: b.type, d: b.d, cli, ht: r2(b.ht), canal: caisse ? 'Particulier' : 'Pro' });
  }
  if (repris.length) {
    tickets.sort((a, b) => (a.d < b.d ? -1 : a.d > b.d ? 1 : 0));
    cpt.sort((a, b) => (a.d < b.d ? -1 : a.d > b.d ? 1 : 0));
    J.remplissage.push(`Ventes reprises des écritures valeur (absentes des autres sources) : ${repris.length} documents, ${r2(repris.reduce((s, x) => s + x.ht, 0))} € HT`);
  }
  if (apparies.length) J.remplissage.push(`Tickets validés dans BC sous un autre numéro : ${apparies.length}`);
  if (ajustes.length) J.remplissage.push(`Documents alignés sur le montant des écritures valeur : ${ajustes.length} (${r2(ajustes.reduce((s, a) => s + a.ecart, 0))} €)`);
  J.remplissage.push(`Commandes ouvertes comptées à leur date de commande : ${nbCmdOuvertes}`);
  facts.sort((a, b) => (a.dF < b.dF ? -1 : a.dF > b.dF ? 1 : 0));

  /* 8. Premières ventes (historique complet) */
  const firstCli = {}, firstArt = {}, lastArt = {};
  for (const f of facts) if (f.t === 'F' && f.ht > 0) {
    if (f.cli && (!firstCli[f.cli] || f.dF < firstCli[f.cli])) firstCli[f.cli] = f.dF;
    if (!f.liv && (!firstArt[f.art] || f.dF < firstArt[f.art])) firstArt[f.art] = f.dF;
    if (!f.liv && (!lastArt[f.art] || f.dF > lastArt[f.art])) lastArt[f.art] = f.dF;
  }
  for (const l of cpt) if (l.ht > 0 && !l.liv && l.d) {
    if (!firstArt[l.art] || l.d < firstArt[l.art]) firstArt[l.art] = l.d;
    if (!lastArt[l.art] || l.d > lastArt[l.art]) lastArt[l.art] = l.d;
  }

  /* 9. Remplissage des champs clés */
  const nF = facts.filter(f => f.t === 'F').length;
  const dF = Object.values(docs).filter(d => d.t === 'F');
  J.remplissage.push(
    `Order_No sur lignes facture : ${pc(nF - src.sansOrderNo, nF)} % ; date commande : archive ${src.archive}, commande ouverte ${src.ouverte}, repli Posting_Date ${src.repli + src.sansOrderNo} (${pc(src.repli + src.sansOrderNo, nF)} %)`,
    `Code postal (livraison ou facturation) : ${pc(dF.filter(d => d.cp).length, dF.length)} % des factures ; Salesperson_Code : ${pc(dF.filter(d => d.vend).length, dF.length)} %`,
    `Caisse : ${nbSales} écritures Sales, ${tickets.length} tickets ; heure (Posting_Date_Time) ${pc(avecHeure, tickets.length)} % ; paiement rapproché ${pc(avecPay, tickets.length)} % ; client identifié ${pc(avecCli, tickets.length)} %`
  );

  /* 10. Contrôles et totaux par plateforme */
  for (const ct of C.controles || []) {
    const pf = C.soc.findIndex(s => s.nom === ct.societe);
    const sel = tickets.filter(t => t.pf === pf && t.d === ct.date);
    const ht = r2(sel.reduce((a, t) => a + t.ht, 0));
    const ok = Math.abs(ht - ct.ht) < 0.01 && sel.length === ct.tickets;
    J.controles.push(`${ok ? 'OK ' : 'KO '} caisse ${ct.societe} ${ct.date} : ${ht} € HT / ${sel.length} tickets (attendu ${ct.ht} € / ${ct.tickets})`);
  }
  if (tickets.length && tickets.reduce((a, t) => a + t.ht, 0) < 0) J.alertes.push('Somme des Sales caisse négative : vérifier le signe de Amount');
  for (let pf = 0; pf < npf; pf++) {
    let fa = 0, av = 0, liv = 0, ca = 0, nt = 0;
    for (const f of facts) if (f.pf === pf) { if (f.t === 'F') fa += f.ht; else av -= f.ht; if (f.liv) liv += f.ht; }
    for (const t of tickets) if (t.pf === pf) { ca += t.ht; nt++; }
    J.totaux.push({ plateforme: C.soc[pf].nom, factures_HT: r2(fa), avoirs_HT: r2(av), pro_net_HT: r2(fa - av), dont_livraison: r2(liv), caisse_HT: r2(ca), tickets: nt });
  }

  /* 11. Contrôle de complétude : partie facturée du dashboard contre les écritures valeur BC */
  function controleCompletude() {
    const manq = (C.manquants || []).filter(m => m.startsWith('valeurs|')).map(m => +m.split('|')[1]);
    const K = { disponible: !!(raw.valeurs && raw.valeurs.some(rows => rows && rows.length)), incomplets: manq.map(pf => toutesSoc[pf]), mois: [], docs: [], autres: [], hors: [], repris, apparies, ajustes, sources: {} };
    K.horsArticles = Object.values(horsArt).map(x => ({ art: x.art, lib: x.lib, lignes: x.lignes, ht: r2(x.ht), pfs: Object.keys(x.pfs).map(Number) })).sort((a, b) => b.ht - a.ht).slice(0, 100);
    K.cmdAnciennes = cmdAnciennes.sort((a, b) => (a.d < b.d ? -1 : a.d > b.d ? 1 : 0)).slice(0, 500);
    K.hors = Object.values(hors).map(h => Object.assign({}, h, { ht: r2(h.ht) })).sort((x, y) => x.pf - y.pf || Math.abs(y.ht) - Math.abs(x.ht));
    K.sources = { dateCommande: { archive: src.archive, ouverte: src.ouverte, repli: src.repli + src.sansOrderNo }, ticketsSansDetail: sansDet, ttcSansDetail: r2(ttcSansDet), commandesOuvertes: nbCmdOuvertes };
    if (!K.disponible) return K;
    const pfIncomplet = new Set(manq);
    const ym = d => d.slice(0, 7);

    // côté dashboard : lignes facturées (factures, avoirs, caisse, lignes facturées des commandes ouvertes)
    const Mo = {};
    const ajouter = (k, pf, d, ht, ic, canal) => {
      const m = Mo[k] || (Mo[k] = { pf, d, ht: 0, ic, canal });
      m.ht += ht;
      if (d && (!m.d || d < m.d)) m.d = d;
    };
    const cle = k => alias[k] || k;     // ticket validé sous un autre numéro : rattaché au document BC
    for (const f of facts) if (!f.cmd) ajouter(cle(f.pf + '|' + f.doc), f.pf, f.dF, f.ht, f.ic, 'Pro');
    for (const k in factCmd) ajouter(k, factCmd[k].pf, factCmd[k].d, factCmd[k].ht, factCmd[k].ic, 'Pro');
    for (const l of cpt) ajouter(cle(cleCaisse(l)), l.pf, l.d, l.ht, l.ic, 'Particulier');

    // comparaison document par document, sur les 4 sociétés T&J
    const parMois = {};
    const agg = (pf, d) => {
      const k = pf + '|' + ym(d);
      return parMois[k] || (parMois[k] = { pf, mois: ym(d), bc: 0, dash: 0, ic: 0, absents: 0, ecarts: 0 });
    };
    const vus = new Set();
    for (const k in B) {
      const b = B[k];
      if (b.pf >= npf || !b.tj) continue;
      vus.add(k);
      const m = Mo[k];
      const cli = cliDoc[k] || '';
      const ic = m ? m.ic : (!!cli && IC.has(cli));
      if (b.d) { const a = agg(b.pf, b.d); if (ic) a.ic += b.ht; else a.bc += b.ht; }
      if (m && !ic && m.d) agg(m.pf, m.d).dash += m.ht;
      const ecart = r2((m ? m.ht : 0) - b.ht);
      if (Math.abs(ecart) <= 0.01) continue;
      if (b.d && !ic) { const a = agg(b.pf, b.d); if (m) a.ecarts++; else a.absents++; }
      let raison = exclus[k] || '';
      if (!raison && ic) raison = 'Client exclu (intersociété ou 000558)';
      if (!raison && pfIncomplet.has(b.pf)) raison = 'Écritures valeur incomplètes pour cette société';
      K.docs.push({ pf: b.pf, doc: b.doc, type: b.type, d: b.d, cli, ic, bc: r2(b.ht), dash: m ? r2(m.ht) : 0, ecart, statut: m ? 'Écart de montant' : 'Absent du dashboard', raison });
    }
    for (const k in Mo) {
      if (vus.has(k)) continue;
      const m = Mo[k];
      if (Math.abs(m.ht) <= 0.01) continue;
      if (!m.ic && m.d) { const a = agg(m.pf, m.d); a.dash += m.ht; a.ecarts++; }
      let raison = m.ic ? 'Client exclu (intersociété ou 000558)' : '';
      if (!raison && m.canal === 'Particulier' && m.d && m.d >= ilYA(3)) raison = 'Ticket récent, pas encore validé dans BC';
      if (!raison && pfIncomplet.has(m.pf)) raison = 'Écritures valeur incomplètes pour cette société';
      K.docs.push({ pf: m.pf, doc: k.slice(k.indexOf('|') + 1), type: m.canal, d: m.d, cli: '', ic: m.ic, bc: 0, dash: r2(m.ht), ecart: r2(m.ht), statut: 'Absent des écritures valeur', raison });
    }
    K.mois = Object.values(parMois).map(a => Object.assign(a, { bc: r2(a.bc), dash: r2(a.dash), ic: r2(a.ic), ecart: r2(a.dash - a.bc) }))
      .sort((x, y) => x.pf - y.pf || (x.mois < y.mois ? -1 : x.mois > y.mois ? 1 : 0));
    K.docs.sort((x, y) => Math.abs(y.ecart) - Math.abs(x.ecart));

    // articles T&J vendus dans les 5 autres sociétés
    const autres = {};
    for (const k in B) {
      const b = B[k];
      if (b.pf < npf || !b.tj || !b.d) continue;
      const ka = b.pf + '|' + ym(b.d);
      const a = autres[ka] || (autres[ka] = { societe: toutesSoc[b.pf], mois: ym(b.d), ht: 0, docs: 0 });
      a.ht += b.ht; a.docs++;
    }
    K.autres = Object.values(autres).map(a => Object.assign(a, { ht: r2(a.ht) })).filter(a => Math.abs(a.ht) > 0.01)
      .sort((x, y) => (x.societe < y.societe ? -1 : x.societe > y.societe ? 1 : x.mois < y.mois ? -1 : 1));

    const nonExpl = K.docs.filter(d => !d.raison);
    if (nonExpl.length) J.alertes.push(`Contrôle de complétude : ${nonExpl.length} documents en écart non expliqués (${r2(nonExpl.reduce((s, d) => s + d.ecart, 0))} €), voir l'onglet Contrôle`);
    if (K.autres.length) J.alertes.push(`Contrôle de complétude : articles T&J vendus hors des 4 sociétés (${r2(K.autres.reduce((s, a) => s + a.ht, 0))} €), voir l'onglet Contrôle`);
    return K;
  }

  const M = {
    v: 1, loadedAt: new Date().toISOString(), pfs: C.soc.map(s => s.court), pfNoms: C.soc.map(s => s.nom),
    tarifsNoms: C.tarifs, tarifs, tj: [...tj], livCodes: [...LIV], facts, docs, tickets, noms, artLib, livLib,
    firstCli, firstArt, lastArt, cpt,
    dMin: facts.length ? facts[0].dF : '', dMax: facts.length ? facts[facts.length - 1].dF : '', erreurs: [],
    controle: controleCompletude()
  };
  J.volumes = { faits_pro: facts.length, documents: Object.keys(docs).length, tickets: tickets.length, lignes_comptoir: cpt.length, articles_tj: tj.size, clients: Object.keys(noms).length };
  J.ms = Date.now() - t0;
  return { M, J };
}


/* =========================================================
   Traitement du message de la collecte
   Sorties : 1 -> debug "Journal de chargement", 2 -> dashboard (diffusion)
   ========================================================= */
const P = msg.payload || {};
const C = Object.assign({}, P.C);
C.manquants = P.manquants || [];
const raw = P.raw || {};
const fr = n => Number(n).toLocaleString('fr-FR');
const jl = [];
const t1 = Date.now();

// 1. Champ du code tarif : configuré, sinon détecté sur les valeurs TJ*_2026
{
  const noms = new Set(C.tarifs);
  let champ = C.champTarif;
  if (!champ) {
    const cnt = {};
    for (const rows of raw.tarifs || []) for (const r of rows) for (const k in r) {
      const v = r[k]; if (typeof v === 'string' && noms.has(v.trim())) cnt[k] = (cnt[k] || 0) + 1;
    }
    champ = Object.keys(cnt).sort((a, b) => cnt[b] - cnt[a])[0] || '';
    jl.push(champ
      ? `Champ du code tarif détecté : ${champ} (${fr(cnt[champ])} lignes TJ). À recopier dans champTarif du nœud Collecte pour filtrer côté BC.`
      : `Champ du code tarif NON trouvé : aucune valeur ${C.tarifs.join(', ')} dans Price_List_Lines_Part_Excel.`);
  }
  let avant = 0, apres = 0;
  (raw.tarifs || []).forEach((rows, pf) => {
    avant += rows.length;
    raw.tarifs[pf] = champ ? rows.filter(r => noms.has(String(r[champ] || '').trim())) : [];
    apres += raw.tarifs[pf].length;
  });
  C.champTarif = champ || '__absent__';
  jl.push(`Lignes de tarif : ${fr(avant)} reçues, ${fr(apres)} sur les 4 tarifs T&J`);
}

// 2. Collecte en échec avec un modèle déjà en mémoire : on garde l'ancien
const prev = flow.get('tj_M');
if (P.errors && P.errors.length && prev) {
  prev.erreurs = [`Rechargement du ${new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' })} en échec (${P.errors.length} requêtes) : données du ${new Date(prev.loadedAt).toLocaleString('fr-FR', { timeZone: 'Europe/Paris' })} conservées.`].concat(P.errors.slice(0, 5));
  flow.set('tj_M', prev);
  const texte = ['=== T&J : rechargement en ÉCHEC, ancien modèle conservé ===', ...P.errors, ...P.alerts].join('\n');
  node.warn(texte);
  node.status({ fill: 'red', shape: 'ring', text: `échec ${P.errors.length} requêtes, ancien modèle conservé` });
  return [{ payload: { resume: 'échec, ancien modèle conservé', texte, errors: P.errors } }, { payload: { type: 'loaded', on: false, loadedAt: prev.loadedAt, erreurs: prev.erreurs } }];
}

// 3. Construction
let res;
try { res = buildModel(raw, C); } catch (e) {
  node.error('T&J : construction du modèle en erreur : ' + e.stack, msg);
  return [null, { payload: { type: 'loaded', on: false, erreurs: ['Construction du modèle en erreur : ' + e.message] } }];
}
const { M, J } = res;
M.erreurs = (P.errors || []).length ? ['Données incomplètes : ' + P.errors.length + ' requêtes BC en échec (voir le journal).'].concat(P.errors.slice(0, 5)) : [];
flow.set('tj_M', M);
J.collecte = { ms: P.ms, pages: P.pages, origine: P.origine, erreurs: P.errors, alertes: P.alerts, champTarif: C.champTarif };
flow.set('tj_J', J);

// 4. Journal lisible
const soc = C.soc.map(s => s.court);
const L = [];
L.push(`=== T&J : chargement ${P.origine} du ${new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' })} ===`);
L.push(`Collecte ${Math.round(P.ms / 1000)} s (${P.pages} pages), construction ${J.ms} ms, total ${Math.round((Date.now() - t1 + P.ms) / 1000)} s`);
L.push('', 'Volumes BC (lignes reçues par entité) : ' + soc.join(' | '));
for (const k in P.stats) L.push(`  ${(P.E && P.E[k] ? P.E[k].ent : k).padEnd(32)} ${P.stats[k].map(fr).join(' | ')}`);
L.push('', ...jl);
if (J.dedup.length) { L.push('', 'Doublons inter-sociétés retirés :'); J.dedup.forEach(d => { L.push(`  ${d.entite} : ${fr(d.retires)}`); d.detail.forEach(x => L.push('    ' + x)); }); }
else L.push('', 'Doublons inter-sociétés : aucun');
L.push('', 'Volumes modèle : ' + Object.entries(J.volumes).map(([k, v]) => `${k} ${fr(v)}`).join(', '));
L.push('', 'Rejets :'); Object.entries(J.rejets).sort((a, b) => b[1] - a[1]).forEach(([k, v]) => L.push(`  ${k} : ${fr(v)}`));
L.push('Ignorés :'); Object.entries(J.ignores).sort((a, b) => b[1] - a[1]).forEach(([k, v]) => L.push(`  ${k} : ${fr(v)}`));
L.push('', 'Remplissage :'); J.remplissage.forEach(x => L.push('  ' + x));
L.push('', 'Contrôles :'); J.controles.forEach(x => L.push('  ' + x));
L.push('', 'Totaux par plateforme (HT) :');
J.totaux.forEach(t => L.push(`  ${t.plateforme.padEnd(22)} factures ${fr(t.factures_HT)} | avoirs ${fr(t.avoirs_HT)} | Pro net ${fr(t.pro_net_HT)} (dont livraison ${fr(t.dont_livraison)}) | comptoir T&J ${fr(t.caisse_HT)} sur ${fr(t.tickets)} tickets`));
const K = M.controle;
if (K && K.disponible) {
  const bc = K.mois.reduce((s, a) => s + a.bc, 0), da = K.mois.reduce((s, a) => s + a.dash, 0);
  L.push('', `Contrôle de complétude (écritures valeur BC, hors intersociété) : BC ${fr(Math.round(bc))} € | dashboard ${fr(Math.round(da))} € | écart ${fr(Math.round(da - bc))} € | ${fr(K.docs.length)} documents en écart dont ${fr(K.docs.filter(d => !d.raison).length)} non expliqués`);
} else {
  L.push('', 'Contrôle de complétude : écritures valeur non chargées');
}
const al = [].concat(P.alerts || [], J.alertes, (P.errors || []).map(e => 'ERREUR ' + e));
if (al.length) { L.push('', 'Alertes :'); al.forEach(x => L.push('  ' + x)); }
const texte = L.join('\n');
node.warn(texte);
const resume = `${fr(J.volumes.faits_pro)} lignes Pro, ${fr(J.volumes.tickets)} tickets, ${Math.round(P.ms / 1000)} s${al.length ? ', ' + al.length + ' alertes' : ''}`;
node.status({ fill: (P.errors || []).length ? 'yellow' : 'green', shape: 'dot', text: resume });
return [{ payload: { resume, texte, journal: J } }, { payload: { type: 'loaded', on: false, loadedAt: M.loadedAt, erreurs: M.erreurs } }];

// @ts-nocheck
/* =========================================================
   T&J : moteur de statistiques (fonction pure)
   TJE.compute(M, filtres, { today, obj, xl }) -> { meta, options, tabs }
