const TJE = (function () {
  const MS = 864e5;
  const r2 = x => (x === null || x === undefined || !isFinite(x) ? x : Math.round((x + (x >= 0 ? 1e-9 : -1e-9)) * 100) / 100);
  const toT = s => Date.parse(s + 'T00:00:00Z');
  const addD = (s, n) => new Date(toT(s) + n * MS).toISOString().slice(0, 10);
  const diffD = (a, b) => Math.round((toT(b) - toT(a)) / MS);
  const dow = s => (new Date(toT(s)).getUTCDay() + 6) % 7;
  const JOURS = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'];
  const MOIS = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];
  const DEPTS = { '67': 'Bas-Rhin', '68': 'Haut-Rhin', '90': 'Territoire de Belfort', '25': 'Doubs', '70': 'Haute-Saône', '88': 'Vosges', '57': 'Moselle', '54': 'Meurthe-et-Moselle', '39': 'Jura', '21': "Côte-d'Or" };
  const COL = { pro: '#2F5D3A', part: '#9A8C6E', fonce: '#1E3A25', clair: '#8FB098', gris: '#5C645D' };
  const DEF = { joursOuvres: [0, 1, 2, 3, 4, 5] };
  const div = (a, b) => (b ? a / b : null);
  const sum = (arr, f) => { let s = 0; for (const x of arr) s += f(x); return s; };
  const lblD = s => s.slice(8, 10) + '/' + s.slice(5, 7);
  const moisLib = ym => MOIS[+ym.slice(5, 7) - 1] + ' ' + ym.slice(0, 4);
  const fq = q => Number(q).toLocaleString('fr-FR', { maximumFractionDigits: 2 });
  function range(du, au) { const o = []; for (let d = du; d <= au && o.length < 3700; d = addD(d, 1)) o.push(d); return o; }
  function isoWeek(s) {
    const t = new Date(toT(s)); t.setUTCDate(t.getUTCDate() - ((t.getUTCDay() + 6) % 7) + 3);
    const f = new Date(Date.UTC(t.getUTCFullYear(), 0, 4)); f.setUTCDate(f.getUTCDate() - ((f.getUTCDay() + 6) % 7) + 3);
    return t.getUTCFullYear() + '-S' + String(1 + Math.round((t - f) / (7 * MS))).padStart(2, '0');
  } const ferCache = {};
  function feries(y) {
    if (ferCache[y]) return ferCache[y];
    const a = y % 19, b = Math.floor(y / 100), c = y % 100, d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3);
    const h = (19 * a + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4, l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor((a + 11 * h + 22 * l) / 451);
    const mo = Math.floor((h + l - 7 * m + 114) / 31), da = ((h + l - 7 * m + 114) % 31) + 1;
    const P = `${y}-${String(mo).padStart(2, '0')}-${String(da).padStart(2, '0')}`;
