    const dd = daily(X, cur, cur.du, cur.au);
    const drows = dd.days.map((d, i) => ({ d, j: JOURS[dow(d)], pro: r2(dd.pro[i]), part: r2(dd.part[i]), tot: r2(dd.pro[i] + dd.part[i]), fac: dd.fac[i], tk: dd.tk[i] }));
    const grp = keyF => { const g = {}, o = []; drows.forEach(r => { const k = keyF(r.d); if (!g[k]) { g[k] = { k, pro: 0, part: 0, tot: 0, fac: 0, tk: 0, n: 0 }; o.push(k); } const x = g[k]; x.pro += r.pro; x.part += r.part; x.tot += r.tot; x.fac += r.fac; x.tk += r.tk; x.n++; }); return o.map(k => { const x = g[k];['pro', 'part', 'tot'].forEach(f => (x[f] = r2(x[f]))); return x; }); };
    const weeks = grp(isoWeek), months = grp(d => d.slice(0, 7)).map(x => Object.assign(x, { lib: moisLib(x.k) }));
    const wd = JOURS.map((j, i) => ({ j, n: 0, tot: 0, pro: 0, part: 0 }));
    drows.forEach(r => { const x = wd[dow(r.d)]; x.n++; x.tot += r.tot; x.pro += r.pro; x.part += r.part; });
    wd.forEach(x => { x.moy = r2(div(x.tot, x.n) || 0); x.mpro = r2(div(x.pro, x.n) || 0); x.mpart = r2(div(x.part, x.n) || 0); });
    // carte de chaleur comptoir
    let hmin = 24, hmax = -1; for (const t of cur.tickets) if (t.h !== null) { hmin = Math.min(hmin, t.h); hmax = Math.max(hmax, t.h); }
    if (hmax < 0) { hmin = 7; hmax = 18; }
    const hours = []; for (let h = hmin; h <= hmax; h++) hours.push(h);
    const m = JOURS.map(() => hours.map(() => 0)), n = JOURS.map(() => hours.map(() => 0));
    for (const t of cur.tickets) if (t.h !== null) { m[t.dow][t.h - hmin] += t.ht; n[t.dow][t.h - hmin]++; }
    // cumul mois de fin de période contre mois précédent
    const m0 = cur.au.slice(0, 8) + '01', mEnd = addD(addD(m0, 31).slice(0, 8) + '01', -1);
    const p0 = addD(m0, -1).slice(0, 8) + '01', pEnd = addD(m0, -1);
    const dc = daily(X, select(X, p0, mEnd), p0, mEnd);
    const cumOf = (a, b) => { const o = []; let s = 0; dc.days.forEach((d, i) => { if (d >= a && d <= b) { s += dc.pro[i] + dc.part[i]; o.push(r2(s)); } }); return o; };
    const cc = cumOf(m0, cur.au), cp = cumOf(p0, pEnd);
    const nd = Math.max(31, cc.length, cp.length);
    const jour = +cur.au.slice(8, 10), jp = Math.min(jour, cp.length);
    const vc = cc[cc.length - 1] || 0, vp = cp[jp - 1] || 0;
    return [
      { type: 'chart', id: 'jour', title: 'CA par jour', cats: dd.days.map(lblD), xcats: dd.days, xcatF: 'date', catT: 'Date', series: [{ n: 'Pro', d: dd.pro.map(r2), c: COL.pro }, { n: 'Particulier', d: dd.part.map(r2), c: COL.part }], stacked: true, f: 'eur0', w: 12, xl: false },
      T('jours', 'Journalier', [c('d', 'Date', 'date'), c('j', 'Jour'), c('pro', 'CA Pro', 'eur'), c('part', 'CA Particulier', 'eur'), c('tot', 'CA total', 'eur'), c('fac', 'Ventes Pro', 'int'), c('tk', 'Tickets', 'int')], drows, { main: true, w: 6 }),
      T('semaines', 'Par semaine ISO', [c('k', 'Semaine'), c('pro', 'CA Pro', 'eur'), c('part', 'CA Particulier', 'eur'), c('tot', 'CA total', 'eur'), c('tk', 'Tickets', 'int')], weeks, { w: 6 }),
      T('mois', 'Par mois', [c('lib', 'Mois'), c('pro', 'CA Pro', 'eur'), c('part', 'CA Particulier', 'eur'), c('tot', 'CA total', 'eur'), c('fac', 'Ventes Pro', 'int'), c('tk', 'Tickets', 'int')], months, { w: 6, nopage: true }),
      { type: 'chart', id: 'jsem', title: 'CA moyen par jour de la semaine', cats: wd.map(x => x.j.slice(0, 3)), xcats: wd.map(x => x.j), xcatF: 'txt', catT: 'Jour', series: [{ n: 'Pro', d: wd.map(x => x.mpro), c: COL.pro }, { n: 'Particulier', d: wd.map(x => x.mpart), c: COL.part }], stacked: true, f: 'eur0', w: 6 },
      { type: 'heat', id: 'heat', title: 'Comptoir : CA par jour et par heure (heure de Paris)', rows: JOURS, cols: hours.map(h => h + 'h'), m: m.map(r => r.map(r2)), n, f: 'eur0', w: 12 },
      {
        type: 'chart', id: 'cumul', title: `Cumul ${moisLib(m0.slice(0, 7))} contre ${moisLib(p0.slice(0, 7))} : ${Math.round(vc).toLocaleString('fr-FR')} € contre ${Math.round(vp).toLocaleString('fr-FR')} € au jour ${jour}${vp ? ' (' + (vc >= vp ? '+' : '') + Math.round((vc / vp - 1) * 1000) / 10 + ' %)' : ''}`,
        cats: Array.from({ length: nd }, (_, i) => String(i + 1)), catT: 'Jour du mois', xcatF: 'txt',
        series: [{ n: moisLib(m0.slice(0, 7)), d: cc, c: COL.pro, kind: 'line' }, { n: moisLib(p0.slice(0, 7)), d: cp, c: COL.part, kind: 'line', da: '6 4' }], f: 'eur0', w: 12
      }
    ];
  }

  function tabPf(X, cur, prev, A) {
    const { M, F } = X;
    const pfs = F.pfs.length ? F.pfs : M.pfs.map((_, i) => i);
    const PAL = ['#2F5D3A', '#9A8C6E', '#8FB098', '#6B5E43', '#1E3A25', '#C9B98E'];
    const rows = pfs.map(pf => {
      const k = kpis(X, byPf(cur, pf)), kp = prev ? kpis(X, byPf(prev, pf)) : null;
      return { pf: M.pfs[pf], ca: k.ca, var: kp && kp.ca ? k.ca / kp.ca - 1 : null, pro: k.pro, part: k.part, fact: k.factures, tk: k.tickets, pp: k.panierPro, pc: k.panierCpt, cli: k.clients, nv: k.nouveaux, av: k.tauxAvoirs, rem: k.remisePct };
    });
    const tot = sum(rows, r => r.ca);
    rows.sort((a, b) => b.ca - a.ca).forEach((r, i) => { r.rang = i + 1; r.pt = div(r.ca, tot); });
    const list = Object.values(A);
    // top 5 articles par plateforme
    const top = [];
    pfs.forEach(pf => {
      const tp = sum(list, a => a.pfs[pf] || 0);
      list.filter(a => (a.pfs[pf] || 0) > 0).sort((a, b) => b.pfs[pf] - a.pfs[pf]).slice(0, 5).forEach((a, i) => top.push({ pf: M.pfs[pf], rang: i + 1, code: a.code, lib: a.lib, ca: r2(a.pfs[pf]), part: div(a.pfs[pf], tp) }));
    });
    // 1. évolution du CA par plateforme (jour jusqu'à 31 jours, semaine ISO jusqu'à 120, mois au-delà)
    const nj = diffD(cur.du, cur.au) + 1;
    const keyF = nj <= 31 ? (d => d) : nj <= 120 ? isoWeek : (d => d.slice(0, 7));
    const lab = k => (nj <= 31 ? lblD(k) : nj <= 120 ? k.slice(5) : moisLib(k));
    const per = [], ix = {}, val = pfs.map(() => ({}));
    pfs.forEach((pf, n) => {
      const dd = daily(X, byPf(cur, pf), cur.du, cur.au);
      dd.days.forEach((d, i) => {
        const k = keyF(d);
        if (ix[k] === undefined) { ix[k] = per.length; per.push(k); }
        val[n][k] = (val[n][k] || 0) + dd.pro[i] + dd.part[i];
      });
    });
    const evo = {
      type: 'chart', id: 'pf_evo', title: `Évolution du CA par plateforme (par ${nj <= 31 ? 'jour' : nj <= 120 ? 'semaine' : 'mois'})`, cats: per.map(lab), xcats: per.map(lab), xcatF: 'txt', catT: nj <= 31 ? 'Date' : nj <= 120 ? 'Semaine' : 'Mois',
      series: pfs.map((pf, n) => ({ n: M.pfs[pf], d: per.map(k => r2(val[n][k] || 0)), c: PAL[pf % PAL.length], kind: 'line' })), f: 'eur0', w: 12, xl: false
    };
    const evoRows = per.map(k => { const o = { per: lab(k), tot: 0 }; pfs.forEach((pf, n) => { o['p' + n] = r2(val[n][k] || 0); o.tot += val[n][k] || 0; }); o.tot = r2(o.tot); return o; });
    const evoT = T('pf_evo_t', 'Évolution du CA par plateforme', [c('per', nj <= 31 ? 'Date' : nj <= 120 ? 'Semaine' : 'Mois')].concat(pfs.map((pf, n) => c('p' + n, M.pfs[pf], 'eur')), c('tot', 'Total', 'eur')), evoRows, { pp: 10 });
    // 2. Pro et Particulier par plateforme
    const mix = {
      type: 'chart', id: 'pf_mix', title: 'CA Pro et Particulier par plateforme', cats: rows.map(r => r.pf), xcatF: 'txt', catT: 'Plateforme',
      series: [{ n: 'Pro', d: rows.map(r => r.pro), c: COL.pro }, { n: 'Particulier', d: rows.map(r => r.part), c: COL.part }], stacked: true, f: 'eur0', w: 6
    };
    // 4. top 5 clients Pro par plateforme
    const topCli = [];
    pfs.forEach(pf => {
      const g = {}; let tp = 0;
      for (const l of cur.lines) if (l.pf === pf && l.cli) { const x = g[l.cli] || (g[l.cli] = { ca: 0, docs: new Set() }); x.ca += l.ht; tp += l.ht; if (l.t === 'F') x.docs.add(vk(l)); }
      Object.keys(g).sort((a, b) => g[b].ca - g[a].ca).slice(0, 5).forEach((cl, i) => topCli.push({ pf: M.pfs[pf], rang: i + 1, code: cl, nom: X.nom(cl), ca: r2(g[cl].ca), part: div(g[cl].ca, tp), fact: g[cl].docs.size }));
    });
    // 5. matrice des 15 premiers articles par plateforme
    const mat = list.filter(a => a.ca > 0 && !a.liv).sort((a, b) => b.ca - a.ca).slice(0, 15).map(a => {
      const o = { code: a.code, lib: a.lib, tot: r2(a.ca) }; let best = -1, bv = 0; const abs = [];
      pfs.forEach((pf, n) => { const v = a.pfs[pf] || 0; o['p' + n] = v ? r2(v) : null; if (v > bv) { bv = v; best = pf; } if (!(v > 0)) abs.push(M.pfs[pf]); });
      o.princ = best >= 0 ? `${M.pfs[best]} ${Math.round((bv / a.ca) * 100)} %` : ''; o.abs = abs.join(', ');
      return o;
    });
    // 9. clients Pro gagnés et perdus par plateforme (actifs sur une période et pas sur l'autre)
    const net = S => { const o = {}; for (const l of S.lines) if (l.cli) { const k = l.pf + '|' + l.cli; o[k] = (o[k] || 0) + l.ht; } return o; };
    const nc = net(cur), np = prev ? net(prev) : {};
    const gp = [], det = [];
    pfs.forEach(pf => {
      let act = 0, g = 0, gCa = 0, p = 0, pCa = 0;
      for (const k in nc) { if (+k.split('|')[0] !== pf || !(nc[k] > 0.005)) continue; act++; if (!(np[k] > 0.005)) { g++; gCa += nc[k]; det.push({ pf: M.pfs[pf], st: 'Gagné', code: k.slice(k.indexOf('|') + 1), ca: r2(nc[k]) }); } }
      for (const k in np) { if (+k.split('|')[0] !== pf || !(np[k] > 0.005)) continue; if (!(nc[k] > 0.005)) { p++; pCa += np[k]; det.push({ pf: M.pfs[pf], st: 'Perdu', code: k.slice(k.indexOf('|') + 1), ca: r2(np[k]) }); } }
      gp.push({ pf: M.pfs[pf], act, g, gCa: r2(gCa), p, pCa: r2(pCa), solde: g - p });
    });
    det.forEach(d => (d.nom = X.nom(d.code)));
    det.sort((a, b) => b.ca - a.ca);
    return [
      T('pf', 'Comparatif des plateformes', [c('rang', 'Rang', 'int'), c('pf', 'Plateforme'), c('ca', 'CA total', 'eur'), c('pt', 'Part', 'pct'), c('var', 'Variation', 'pct'), c('pro', 'CA Pro', 'eur'), c('part', 'CA Particulier', 'eur'), c('fact', 'Ventes', 'int'), c('tk', 'Tickets', 'int'), c('pp', 'Panier Pro', 'eur'), c('pc', 'Panier comptoir', 'eur'), c('cli', 'Clients actifs', 'int'), c('nv', 'Nouveaux', 'int'), c('av', 'Taux avoirs', 'pct'), c('rem', 'Remise', 'pct')], rows, { main: true, nopage: true, signed: 'var' }),
      evo,
      evoT,
      mix,
      T('pf_gp', `Clients Pro gagnés et perdus (${lblD(cur.du)} au ${lblD(cur.au)} contre ${prev ? lblD(prev.du) + ' au ' + lblD(prev.au) : 'période précédente'})`, [c('pf', 'Plateforme'), c('act', 'Actifs', 'int'), c('g', 'Gagnés', 'int'), c('gCa', 'CA des gagnés', 'eur'), c('p', 'Perdus', 'int'), c('pCa', 'CA perdu (période préc.)', 'eur'), c('solde', 'Solde', 'int')], gp, { w: 6, nopage: true, signed: 'solde' }),
      T('pf_top', 'Top 5 articles par plateforme', [c('pf', 'Plateforme'), c('rang', 'Rang', 'int'), c('code', 'Code', 'code'), c('lib', 'Article'), c('ca', 'CA HT', 'eur'), c('part', 'Part plateforme', 'pct')], top, { w: 6, click: 'article', pp: 20 }),
      T('pf_cli', 'Top 5 clients Pro par plateforme', [c('pf', 'Plateforme'), c('rang', 'Rang', 'int'), c('code', 'Code', 'code'), c('nom', 'Client'), c('ca', 'CA HT', 'eur'), c('part', 'Part plateforme', 'pct'), c('fact', 'Ventes', 'int')], topCli, { w: 6, click: 'client', pp: 20 }),
      T('pf_mat', 'Les 15 premiers articles par plateforme', [c('code', 'Code', 'code'), c('lib', 'Article')].concat(pfs.map((pf, n) => c('p' + n, M.pfs[pf], 'eur')), c('tot', 'Total', 'eur'), c('princ', 'Plateforme principale'), c('abs', 'Absent de')), mat, { click: 'article', nopage: true }),
      T('pf_gp_d', 'Détail des clients Pro gagnés et perdus', [c('pf', 'Plateforme'), c('st', 'Statut'), c('code', 'Code', 'code'), c('nom', 'Client'), c('ca', 'CA HT', 'eur')], det, { click: 'client', sort: 'ca' })
    ];
  }

  function tabComptoir(X, cur) {
    const { M, F } = X;
    if (F.canal === 'pro') return [N('cpt_pro', 'Canal Pro sélectionné : pas de comptoir.', 'warn')];
    const tk = cur.tickets, ca = sum(tk, t => t.ht);
    const Ac = Object.values(aggArt(X, cur.cpt)).sort((a, b) => b.ca - a.ca), totL = sum(Ac, a => a.ca);
    const grp = keyF => { const g = {}; for (const t of tk) { const k = keyF(t); const x = g[k] || (g[k] = { k, ca: 0, n: 0 }); x.ca += t.ht; x.n++; } return Object.values(g).map(x => ({ k: x.k, ca: r2(x.ca), n: x.n, panier: r2(div(x.ca, x.n)), part: div(x.ca, ca) })).sort((a, b) => b.ca - a.ca); };
    const caisses = grp(t => M.pfs[t.pf] + ' / ' + (t.caisse || '?'));
    const pm = {};
    for (const t of tk) for (const m in t.pm) { const x = pm[m] || (pm[m] = { ca: 0, n: 0 }); x.ca += t.ht * t.pm[m]; x.n++; }
    const pmRows = Object.keys(pm).map(m => ({ k: m, ca: r2(pm[m].ca), part: div(pm[m].ca, ca), n: pm[m].n })).sort((a, b) => b.ca - a.ca);
    /** @type {Array<[string, number, number]>} */
    const B = [['0 à 20 €', -1e9, 20], ['20 à 50 €', 20, 50], ['50 à 100 €', 50, 100], ['100 à 200 €', 100, 200], ['200 € et plus', 200, 1e12]];
    const bk = B.map(([l, a, z]) => { const s = tk.filter(t => t.ht >= a && t.ht < z); return { l, n: s.length, ca: r2(sum(s, t => t.ht)), p: div(s.length, tk.length) }; });
    const idn = tk.filter(t => t.cli);
    const hrs = {}; let nh = 0; for (const t of tk) if (t.h !== null) { hrs[t.h] = (hrs[t.h] || 0) + 1; nh++; }
    const hk = Object.keys(hrs).map(Number).sort((a, b) => a - b);
    const jours = new Set(tk.map(t => t.d)).size;
    const blocks = [
      {
        type: 'kpis', id: 'cpt_k', w: 12, items: [
          { k: 'ca', l: 'CA comptoir HT', v: r2(ca), f: 'eur0' },
          { k: 'tk', l: 'Tickets', v: tk.length, f: 'int', sub: { t: '{v} par jour de vente', v: r2(div(tk.length, jours)), f: 'num' } },
          { k: 'pan', l: 'Panier moyen', v: r2(div(ca, tk.length)), f: 'eur' },
          { k: 'idn', l: 'Clients identifiés', v: div(idn.length, tk.length), f: 'pct', sub: { t: '{v} du CA', v: div(sum(idn, t => t.ht), ca), f: 'pct' } }
        ]
      },
      T('cpt_art', 'Articles vendus au comptoir', [c('code', 'Code', 'code'), c('lib', 'Article'), c('ca', 'CA HT', 'eur'), c('part', 'Part', 'pct'), c('qte', 'Quantités par unité'), c('tks', 'Tickets', 'int'), c('clis', 'Clients identifiés', 'int')],
        Ac.map(a => ({ code: a.code, lib: a.lib + (a.liv ? ' (livraison)' : ''), ca: r2(a.ca), part: div(a.ca, totL), qte: qtxt(a), tks: a.tks.size, clis: a.clis.size })), { click: 'article', sort: 'ca' }),
      T('cpt_caisse', 'Par caisse', [c('k', 'Plateforme / caisse'), c('ca', 'CA HT', 'eur'), c('n', 'Tickets', 'int'), c('panier', 'Panier moyen', 'eur'), c('part', 'Part', 'pct')], caisses, { w: 6, main: true }),
      HB('cpt_pm', 'Modes de paiement (CA HT réparti au prorata des règlements)', pmRows.map(r => ({ l: r.k, v: r.ca })), 'eur0', { xl: false }),
      T('cpt_pm_t', 'Modes de paiement', [c('k', 'Mode'), c('ca', 'CA HT', 'eur'), c('part', 'Part', 'pct'), c('n', 'Tickets', 'int')], pmRows, { w: 6, nopage: true }),
      { type: 'chart', id: 'cpt_bk', title: 'Distribution des paniers (tickets)', cats: bk.map(b => b.l), xcatF: 'txt', catT: 'Tranche', series: [{ n: 'Tickets', d: bk.map(b => b.n), c: COL.part }], f: 'int', w: 6, xl: false },
      T('cpt_bk_t', 'Tranches de panier', [c('l', 'Tranche'), c('n', 'Tickets', 'int'), c('p', 'Part des tickets', 'pct'), c('ca', 'CA HT', 'eur')], bk, { w: 6, nopage: true }),
      { type: 'chart', id: 'cpt_h', title: `Affluence par heure (tickets, heure de Paris${nh < tk.length ? ', ' + (tk.length - nh) + ' tickets sans heure' : ''})`, cats: hk.map(h => h + 'h'), xcatF: 'txt', catT: 'Heure', series: [{ n: 'Tickets', d: hk.map(h => hrs[h]), c: COL.pro }, { n: 'Moyenne par jour', d: hk.map(h => r2(hrs[h] / (jours || 1))), c: COL.fonce, kind: 'line', ax: 2 }], f: 'int', f2: 'num', w: 12 }
    ];
    if (X.xl) blocks.push(T('cpt_tickets', 'Tickets', [c('pf', 'Plateforme'), c('d', 'Date', 'date'), c('h', 'Heure', 'int'), c('rec', 'Ticket', 'code'), c('caisse', 'Caisse', 'code'), c('vend', 'Vendeur', 'code'), c('cli', 'Client', 'code'), c('nom', 'Nom'), c('ht', 'CA HT', 'eur'), c('pm', 'Mode principal')],
      tk.map(t => ({ pf: M.pfs[t.pf], d: t.d, h: t.h, rec: t.rec, caisse: t.caisse, vend: t.vend, cli: t.cli, nom: X.nom(t.cli), ht: t.ht, pm: Object.keys(t.pm).sort((a, b) => t.pm[b] - t.pm[a])[0] })), { xlOnly: true }));
    if (X.xl) blocks.push(T('cpt_lignes', 'Lignes article comptoir', [c('pf', 'Plateforme'), c('d', 'Date', 'date'), c('rec', 'Ticket', 'code'), c('doc', 'Document BC', 'code'), c('art', 'Article', 'code'), c('lib', 'Libellé'), c('u', 'Unité', 'code'), c('q', 'Quantité', 'num'), c('ht', 'Montant HT', 'eur'), c('cli', 'Client', 'code')],
      cur.cpt.map(l => ({ pf: M.pfs[l.pf], d: l.d, rec: l.tk ? l.tk.slice(l.tk.indexOf('|') + 1) : '', doc: l.doc, art: l.art, lib: X.lib(l.art), u: l.u, q: r2(l.q), ht: r2(l.ht), cli: l.cli })), { xlOnly: true }));
    return blocks;
  }



  /* ---------- contrôle de complétude (calculé au chargement, indépendant des filtres) ---------- */
  function tabControle(X) {
