      blocks.push(N('ctl_indispo', 'Écritures valeur BC non chargées lors du dernier chargement : rapprochement impossible (voir le journal de chargement).', 'warn'));
    } else {
      if (K.incomplets.length) blocks.push(N('ctl_inc', 'Écritures valeur incomplètes pour : ' + K.incomplets.join(', ') + '. Les écarts de ces sociétés ne sont pas fiables.', 'warn'));
      const totBc = sum(K.mois, a => a.bc), totDash = sum(K.mois, a => a.dash);
      const nonExpl = K.docs.filter(d => !d.raison);
      blocks.push(N('ctl_note', 'Rapprochement de la partie facturée du dashboard avec les écritures valeur BC, qui enregistrent toute vente d’article validée (facture, avoir, caisse), quel que soit son chemin. Les commandes ouvertes non facturées, comptées dans le dashboard, n’y figurent pas encore. Montants HT nets de remise, par date de comptabilisation, articles des 4 tarifs T&J et codes livraison, hors clients exclus (01 à 12 et 000558). Indépendant des filtres.', 'info'));
      blocks.push({
        type: 'kpis', id: 'ctl_k', w: 12, items: [
          { k: 'bc', l: 'Écritures valeur BC', v: r2(totBc), f: 'eur0' },
          { k: 'dash', l: 'Dashboard, partie facturée', v: r2(totDash), f: 'eur0' },
