          { k: 'nonexpl', l: 'Documents en écart non expliqués', v: nonExpl.length, f: 'int', good: -1, sub: { t: '{v} au total', v: r2(sum(nonExpl, d => d.ecart)), f: 'eur0' } },
          { k: 'autres', l: 'Ventes T&J hors des 4 sociétés', v: r2(sum(K.autres, a => a.ht)), f: 'eur0', good: -1 },
