        ]
      });
      blocks.push(T('ctl_mois', 'Par plateforme et par mois (date de comptabilisation)', [c('pf', 'Plateforme'), c('mois', 'Mois'), c('bc', 'Écritures valeur BC', 'eur'), c('dash', 'Dashboard', 'eur'), c('ecart', 'Écart', 'eur'), c('absents', 'Documents absents', 'int'), c('ecarts', 'Documents en écart', 'int'), c('ic', 'Intersociété exclu', 'eur')],
