      blocks.push(T('ctl_docs', `Documents en écart : ${K.docs.length}, dont ${nonExpl.length} non expliqués`, [c('pf', 'Plateforme'), c('doc', 'Document', 'code'), c('type', 'Type'), c('d', 'Date', 'date'), c('cli', 'Client', 'code'), c('nom', 'Nom'), c('bc', 'Écritures valeur BC', 'eur'), c('dash', 'Dashboard', 'eur'), c('ecart', 'Écart', 'eur'), c('statut', 'Statut'), c('raison', 'Explication')],
        K.docs.map(d => Object.assign({}, d, { pf: nomPf(d.pf), nom: X.nom(d.cli), raison: d.raison || 'Non expliqué' })), { signed: 'ecart', pp: 25 }));
      blocks.push(T('ctl_repris', 'Ventes reprises des écritures valeur (absentes des autres sources, ajoutées au dashboard)', [c('pf', 'Plateforme'), c('doc', 'Document', 'code'), c('type', 'Type'), c('d', 'Date', 'date'), c('canal', 'Canal'), c('cli', 'Client', 'code'), c('ht', 'Montant HT', 'eur')],
