      blocks.push(T('ctl_apparies', 'Tickets validés dans BC sous un autre numéro (même jour, même montant : comptés une seule fois)', [c('pf', 'Plateforme'), c('d', 'Date', 'date'), c('ticket', 'Document caisse', 'code'), c('doc', 'Document BC', 'code'), c('ht', 'Montant HT', 'eur')],
        (K.apparies || []).map(x => Object.assign({}, x, { pf: nomPf(x.pf) })), { w: 6, pp: 15 }));
      blocks.push(T('ctl_ajustes', 'Montants alignés sur les écritures valeur (remise ou frais répartis sur les articles)', [c('pf', 'Plateforme'), c('doc', 'Document', 'code'), c('d', 'Date', 'date'), c('avant', 'Lignes du document', 'eur'), c('apres', 'Écritures valeur BC', 'eur'), c('ecart', 'Écart', 'eur')],
        (K.ajustes || []).map(x => Object.assign({}, x, { pf: nomPf(x.pf) })), { w: 6, pp: 15, signed: 'ecart' }));
      blocks.push(T('ctl_autres', 'Articles T&J vendus dans les autres sociétés', [c('societe', 'Société'), c('mois', 'Mois'), c('ht', 'Montant HT', 'eur'), c('docs', 'Documents', 'int')], K.autres, { w: 6, nopage: true }));
    }
    blocks.push(T('ctl_cmd_anc', 'Commandes ouvertes de plus de 60 jours (comptées dans le CA à leur date de commande : à solder ou supprimer dans BC si abandonnées)', [c('pf', 'Plateforme'), c('no', 'Commande', 'code'), c('d', 'Date', 'date'), c('age', 'Âge (j)', 'int'), c('cli', 'Client', 'code'), c('nom', 'Nom'), c('ht', 'Montant T&J HT', 'eur')],
      (K.cmdAnciennes || []).map(x => Object.assign({}, x, { pf: nomPf(x.pf), nom: X.nom(x.cli) })), { pp: 15, sort: 'ht', click: 'client' }));
    blocks.push(T('ctl_hors_art', 'Articles hors des 4 tarifs vendus dans des documents T&J (non comptés : à ajouter à un tarif s’ils sont T&J)', [c('art', 'Article', 'code'), c('lib', 'Libellé'), c('pfs', 'Plateformes'), c('lignes', 'Lignes', 'int'), c('ht', 'Montant HT', 'eur')],
      (K.horsArticles || []).map(x => Object.assign({}, x, { pfs: (x.pfs || []).map(nomPf).join(', ') })), { pp: 15, sort: 'ht' }));
    blocks.push(T('ctl_hors', 'Lignes écartées des documents T&J (hors périmètre, ni dans le dashboard ni dans le rapprochement)', [c('pf', 'Plateforme'), c('type', 'Type de ligne'), c('lignes', 'Lignes', 'int'), c('ht', 'Montant HT', 'eur')],
      K.hors.map(h => Object.assign({}, h, { pf: nomPf(h.pf) })), { w: 6, nopage: true }));
    const s = K.sources, dc = s.dateCommande, nd = dc.archive + dc.ouverte + dc.repli;
    blocks.push(N('ctl_src', `Commandes ouvertes comptées à leur date de commande : ${s.commandesOuvertes || 0}. Date de commande des lignes facturées : archive ${dc.archive}, commande ouverte ${dc.ouverte}, date de facture faute de commande ${dc.repli}${nd ? ' (' + Math.round((dc.repli / nd) * 100) + ' %)' : ''}. Tickets de caisse sans pièce justificative : ${s.ticketsSansDetail} (${Number(s.ttcSansDetail).toLocaleString('fr-FR')} € TTC), repris des écritures valeur quand elles existent.`, 'info'));
    return blocks;
  }

  function lignes(X, cur) {
    const { M } = X;
    const rows = cur.lines.map(l => ({ canal: 'Pro', type: l.t === 'F' ? (l.cmd ? 'Commande ouverte' : 'Facture') : 'Avoir', doc: l.doc, dF: l.cmd ? null : l.dF, dC: l.dCs === 1 ? l.dC : null, pf: M.pfs[l.pf], cli: l.cli, nom: X.nom(l.cli), cp: l.cp, art: l.art, lib: X.lib(l.art), u: l.u, q: r2(l.q), ht: r2(l.ht), brut: r2(l.brut), rem: r2(l.rem), liv: l.liv ? 'Oui' : 'Non', vend: l.vend, ord: l.ord, caisse: '', h: null }));
    for (const t of cur.tickets) rows.push({ canal: 'Particulier', type: 'Ticket', doc: t.rec, dF: t.d, dC: null, pf: M.pfs[t.pf], cli: t.cli, nom: X.nom(t.cli), cp: '', art: '', lib: '', u: '', q: null, ht: t.ht, brut: t.ht, rem: 0, liv: 'Non', vend: t.vend, ord: '', caisse: t.caisse, h: t.h });
    return [T('lignes', 'Lignes', [c('canal', 'Canal'), c('type', 'Type'), c('doc', 'Document', 'code'), c('dF', 'Date facturation', 'date'), c('dC', 'Date commande', 'date'), c('pf', 'Plateforme'), c('cli', 'Client', 'code'), c('nom', 'Nom'), c('cp', 'CP', 'code'), c('art', 'Article', 'code'), c('lib', 'Libellé'), c('u', 'Unité', 'code'), c('q', 'Quantité', 'num'), c('ht', 'Montant HT', 'eur'), c('brut', 'Brut HT', 'eur'), c('rem', 'Remise', 'eur'), c('liv', 'Livraison'), c('vend', 'Vendeur', 'code'), c('ord', 'Commande', 'code'), c('caisse', 'Caisse', 'code'), c('h', 'Heure', 'int')], rows, { main: true, xlOnly: true })];
  }


  function options(X) {
    const { M, F } = X;
    const base = select(X, F.du, F.au, { noCli: true, noArt: true });
    const sa = F.articles.length ? new Set(F.articles) : null, sc = F.clients.length ? new Set(F.clients) : null;
    const cs = new Set(), as = new Set();
    for (const l of base.lines) { if (!sa || sa.has(l.art)) cs.add(l.cli); if (!sc || sc.has(l.cli)) as.add(l.art); }
    if (!sa) for (const t of base.tickets) if (t.cli) cs.add(t.cli);
    for (const l of base.cpt) { if (l.cli && (!sa || sa.has(l.art))) cs.add(l.cli); if (!sc || sc.has(l.cli)) as.add(l.art); }
    F.clients.forEach(x => cs.add(x)); F.articles.forEach(x => as.add(x));
    return {
      clients: [...cs].filter(Boolean).map(v => ({ v, t: (M.noms[v] || '?') + ' (' + v + ')' })).sort((a, b) => a.t.localeCompare(b.t, 'fr')),
      articles: [...as].filter(Boolean).sort().map(v => ({ v, t: v + ' ' + (M.artLib[v] || '') }))
    };
  }
  function resume(X) {
    const { M, F } = X;
    return [
      ['Période', `${F.du} au ${F.au}`], ['Comparée à', `${X.pdu} au ${X.pau}`], ['Date de référence', 'Commande (factures directes et avoirs : facturation)'],
      ['Plateformes', F.pfs.length ? F.pfs.map(i => M.pfs[i]).join(', ') : 'Toutes'], ['Canal', { all: 'Tout', pro: 'Pro', part: 'Particulier' }[F.canal]],
      ['Clients', F.clients.length ? F.clients.join(', ') : 'Tous'], ['Articles', F.articles.length ? F.articles.join(', ') : 'Tous'], ['Données BC au', M.loadedAt]
    ];
  }


  function compute(M, F0, o) {
    const t0 = Date.now();
    const X = ctx(M, F0, o); const F = X.F;
    const cur = select(X, F.du, F.au);
    let prev = null;
    if (F.cmp === 'prev') { const len = diffD(F.du, F.au) + 1; X.pau = addD(F.du, -1); X.pdu = addD(X.pau, -(len - 1)); prev = select(X, X.pdu, X.pau); }
    const k = kpis(X, cur), kp = prev ? kpis(X, prev) : null;
    const A = aggArt(X, cur.lines.concat(cur.cpt)), Cl = aggCli(X, cur.lines.filter(l => l.cli));
    const tabs = {
      vue: tabVue(X, cur, k, kp, A, Cl),
      articles: tabArticles(X, cur, A),
      clients: tabClients(X, cur, Cl),
      temps: tabTemps(X, cur),
      plateformes: tabPf(X, cur, prev, A),
      comptoir: tabComptoir(X, cur),
      controle: tabControle(X)
    };
    if (X.xl) tabs.lignes = lignes(X, cur);
    const F2 = Object.assign({}, F); delete F2.params;
    return {
      meta: { loadedAt: M.loadedAt, today: X.today, du: F.du, au: F.au, pdu: X.pdu || null, pau: X.pau || null, ms: Date.now() - t0, erreurs: M.erreurs || [], pfs: M.pfs, tarifs: M.tarifsNoms, dMin: M.dMin, dMax: M.dMax, lignes: cur.lines.length, tickets: cur.tickets.length },
      filtres: F2, params: F.params, resume: resume(X), options: options(X), tabs
    };
  }

  function fiche(M, F0, kind, code, o) {
    const X = ctx(M, F0, o); const F = X.F;
    if (kind === 'article') F.articles = [code]; else F.clients = [code];
    const cur = select(X, F.du, F.au);
    const blocks = [];
    if (kind === 'article') {
      const a = aggArt(X, cur.lines.concat(cur.cpt))[code];
      if (!a) return { title: `${code} ${X.lib(code)}`, blocks: [N('vide', 'Aucune vente sur la période avec les filtres actuels.', 'warn')] };
      blocks.push({
        type: 'kpis', id: 'fa_k', w: 12, items: [
          { k: 'ca', l: 'CA HT', v: r2(a.ca), f: 'eur0', sub: { t: 'dont Particulier {v}', v: r2(a.caPart), f: 'eur0' } }, { k: 'docs', l: 'Ventes Pro', v: a.docs.size, f: 'int' }, { k: 'tks', l: 'Tickets comptoir', v: a.tks.size, f: 'int' }, { k: 'clis', l: 'Clients', v: a.clis.size, f: 'int' },
          { k: 'rem', l: 'Remise moyenne', v: div(a.rem, a.brut), f: 'pct' }, { k: 'first', l: 'Première vente', v: M.firstArt[code] || null, f: 'date' }
        ]
      });
      blocks.push(T('fa_u', 'Quantités et prix par canal et par unité, contre les 4 tarifs T&J', [c('canal', 'Canal'), c('u', 'Unité'), c('q', 'Quantité', 'num'), c('ca', 'CA HT', 'eur'), c('pm', 'Prix moyen réel', 'eur')].concat(colsTarifs(M)),
        Object.keys(a.uc).map(uk => { const [canal, u] = uk.split('|'), x = a.uc[uk], pm = x.q ? x.ca / x.q : null; return Object.assign({ canal, u, q: r2(x.q), ca: r2(x.ca), pm: r2(pm) }, prixTarifs(M, code, u, pm)); }), { w: 12, nopage: true, signed: 'ecart' }));
      blocks.push(HB('fa_pf', 'Répartition par plateforme', Object.keys(a.pfs).map(p => ({ l: M.pfs[p], v: a.pfs[p] })).sort((x, y) => y.v - x.v), 'eur0'));
      blocks.push(serie(X, cur, 'Évolution du CA', 'fa_s'));
      const cl = Object.values(aggCli(X, cur.lines.concat(cur.cpt).filter(l => l.cli))).sort((x, y) => y.ca - x.ca);
      blocks.push(T('fa_cli', 'Top clients', [c('code', 'Code', 'code'), c('nom', 'Client'), c('ca', 'CA HT', 'eur'), c('part', 'Part', 'pct'), c('fact', 'Ventes', 'int')], cl.map(x => ({ code: x.code, nom: x.nom, ca: r2(x.ca), part: div(x.ca, a.ca), fact: x.docs.size })), { click: 'client', sort: 'ca' }));
      return { title: `${code} ${X.lib(code)}`, blocks };
    }
    const H = hist(X)[code], k = kpis(X, cur);
    blocks.push({
      type: 'kpis', id: 'fc_k', w: 12, items: [
        { k: 'ca', l: 'CA HT période', v: k.ca, f: 'eur0' }, { k: 'fact', l: 'Ventes Pro', v: k.factures, f: 'int' }, { k: 'pan', l: 'Panier moyen', v: k.panierPro, f: 'eur' },
        { k: 'tk', l: 'Tickets comptoir', v: k.tickets, f: 'int' }, { k: 'der', l: 'Dernier achat', v: H ? H.last : null, f: 'date' },
        { k: 'freq', l: 'Fréquence', v: H && H.freq !== null ? r2(H.freq) : null, f: 'days' }
      ]
    });
    blocks.push(serie(X, cur, 'Évolution du CA', 'fc_s'));
    const A = Object.values(aggArt(X, cur.lines.concat(cur.cpt))).sort((x, y) => y.ca - x.ca);
    blocks.push(T('fc_art', 'Articles achetés', [c('code', 'Code', 'code'), c('lib', 'Article'), c('ca', 'CA HT', 'eur'), c('caPart', 'dont comptoir', 'eur'), c('qte', 'Quantités'), c('docs', 'Ventes', 'int'), c('tks', 'Tickets', 'int'), c('rem', 'Remise', 'pct')], A.map(x => ({ code: x.code, lib: x.lib, ca: r2(x.ca), caPart: r2(x.caPart), qte: qtxt(x), docs: x.docs.size, tks: x.tks.size, rem: div(x.rem, x.brut) })), { click: 'article', sort: 'ca' }));
    return { title: `${X.nom(code) || '?'} (${code})`, blocks };
  }

  return { compute, fiche, DEF, _: { isoWeek, feries, addD, diffD } };
})();


/* =========================================================
   Routage des demandes du dashboard
   Sorties : 1 -> ui-template (réponse au seul demandeur via _client, ou diffusion)
             2 -> Export Excel, 3 -> Collecte (rechargement)
   ========================================================= */
const p = msg.payload || {};
const M = flow.get('tj_M');
const today = (() => { const o = {}; for (const x of new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date())) o[x.type] = x.value; return `${o.year}-${o.month}-${o.day}`; })();
const reply = pl => ({ _client: msg._client, payload: Object.assign({ cid: p.cid, rid: p.rid }, pl) });
function etat() {
  const R = flow.get('tj_run');
  return {
    loadedAt: M ? M.loadedAt : null, erreurs: M ? M.erreurs || [] : [], dMin: M ? M.dMin : null, dMax: M ? M.dMax : null, today,
    run: R && !R.fini ? { on: true, pct: R.total ? Math.min(95, Math.round((R.done / R.total) * 95)) : 0, text: `Collecte BC : ${R.done}/${R.total} requêtes` } : null
  };
}
const obj = () => flow.get('tj_obj') || {};

// =========================================================
// data-tools : réponses HTTP (/dt-api/tj-commercial/<action>)
// Appel HTTP = msg.res présent. La page Dashboard 2.0 continue
// de passer par le code habituel plus bas.
// Sortie 4 -> http response ; sortie 2 -> Export Excel ; sortie 3 -> Collecte
// =========================================================
const viaHttp = !!msg.res;
if (viaHttp) {
  const DETAIL_MAX = 2000;                        // lignes par tableau envoyées au navigateur
  const CHARGEMENT_MAX_MS = 45 * 60 * 1000;
  const chemin = String((msg.req && (msg.req.path || msg.req.url)) || '');
  const action = chemin.split('?')[0].replace(/\/+$/, '').split('/').pop();
  const methode = String((msg.req && msg.req.method) || 'GET').toUpperCase();
  const corps = msg.payload && typeof msg.payload === 'object' && !Buffer.isBuffer(msg.payload) ? msg.payload : {};
  const utilisateur = msg.dtUser || {};
  const admin = !!utilisateur.admin;

  const repondre = function (code, contenu) {
    msg.statusCode = code;
    msg.payload = contenu;
    msg.headers = { 'Cache-Control': 'no-store' };
    return [null, null, null, msg];
  };
  const refuser = function (code, erreur, texte) {
    return repondre(code, { erreur: erreur, message: texte });
  };

  // Les grands tableaux sont limités : le navigateur n'en affiche qu'une page.
  // L'export Excel, lui, reste complet.
  const alleger = function (blocs) {
    return (blocs || []).filter(function (b) { return !b.xlOnly; }).map(function (b) {
      if (b.type !== 'table' || !Array.isArray(b.rows) || b.rows.length <= DETAIL_MAX) return b;
      let lignes = b.rows;
      if (b.sort) {
        lignes = lignes.slice().sort(function (x, y) { return (Number(y[b.sort]) || 0) - (Number(x[b.sort]) || 0); });
      }
      return Object.assign({}, b, { rows: lignes.slice(0, DETAIL_MAX), total: b.rows.length, tronque: true });
    });
  };

  try {
    switch (action) {

      case 'meta':
        return repondre(200, {
          etat: etat(),
          admin: admin,
          pfs: M ? M.pfs : [],
          tarifs: M ? M.tarifsNoms : [],
          objectifs: obj()
        });

      case 'statut':
        return repondre(200, { etat: etat(), admin: admin });

      case 'requete': {
        if (!M) return repondre(200, { nodata: true, etat: etat() });
        const data = TJE.compute(M, corps.filtres || {}, { today, obj: obj() });
        data.etat = etat();
        for (const onglet in data.tabs) data.tabs[onglet] = alleger(data.tabs[onglet]);
        node.status({ fill: 'green', shape: 'dot', text: 'data-tools : calcul ' + data.meta.ms + ' ms (' + (utilisateur.login || '?') + ')' });
        return repondre(200, data);
      }

      case 'fiche-article':
      case 'fiche-client': {
        if (!M) return refuser(409, 'aucune_donnee', 'Aucune donnée chargée.');
        const code = String(corps.code || '').trim();
        if (!code) return refuser(400, 'code_manquant', 'Code article ou client manquant.');
        const kind = action === 'fiche-article' ? 'article' : 'client';
        const fiche = TJE.fiche(M, corps.filtres || {}, kind, code, { today });
        return repondre(200, { kind: kind, code: code, title: fiche.title, blocks: alleger(fiche.blocks) });
      }

      case 'objectifs': {
        if (methode === 'GET') return repondre(200, { objectifs: obj(), pfs: M ? M.pfs : [], admin: admin });
        if (!admin) return refuser(403, 'admin_requis', 'Saisie des objectifs réservée aux administrateurs.');
        if (!M) return refuser(409, 'aucune_donnee', 'Aucune donnée chargée.');
        if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(String(corps.ym))) return refuser(400, 'mois_invalide', 'Mois invalide (attendu AAAA-MM).');
        const O = obj();
        const valeurs = {};
        for (const pf of M.pfs) {
          const n = Number(String((corps.vals || {})[pf] ?? '').replace(',', '.'));
          if (isFinite(n) && n > 0) valeurs[pf] = Math.round(n * 100) / 100;
        }
        if (Object.keys(valeurs).length) O[corps.ym] = valeurs; else delete O[corps.ym];
        flow.set('tj_obj', O);
        node.warn('Objectifs ' + corps.ym + ' enregistrés par ' + (utilisateur.login || '?') + ' (data-tools)');
        return repondre(200, { enregistre: true, ym: corps.ym, objectifs: O });
      }

      case 'export': {
        if (!M) return refuser(409, 'aucune_donnee', 'Aucune donnée chargée.');
        const dataXl = TJE.compute(M, corps.filtres || {}, { today, obj: obj(), xl: true });
        msg.payload = { data: dataXl };
        return [null, msg, null, null];
      }

      case 'recharger': {
        if (!admin) return refuser(403, 'admin_requis', 'Rechargement réservé aux administrateurs.');
        const R = flow.get('tj_run');
        if (R && !R.fini && Date.now() - R.t0 < CHARGEMENT_MAX_MS) {
          return refuser(409, 'chargement_en_cours', 'Un chargement BC est déjà en cours (' + (R.done || 0) + '/' + (R.total || 0) + ' requêtes).');
        }
        node.warn('Rechargement BC demandé par ' + (utilisateur.login || '?') + ' (data-tools)');
        const declenchement = { topic: 'data-tools' };
        msg.statusCode = 202;
        msg.payload = { lance: true, message: 'Chargement BC lancé' };
        msg.headers = { 'Cache-Control': 'no-store' };
        return [null, null, declenchement, msg];
      }

      default:
        return refuser(404, 'action_inconnue', 'Action inconnue : ' + action);
    }
  } catch (e) {
    node.error('T&J data-tools : ' + (e.stack || e), msg);
    return refuser(500, 'erreur_calcul', 'Erreur de calcul : ' + e.message);
  }
}

try {
  switch (p.type) {
    case 'compute': {
      if (!M) return [reply({ type: 'nodata', etat: etat() }), null, null];
      const data = TJE.compute(M, p.filtres, { today, obj: obj() });
      data.etat = etat();
      node.status({ fill: 'green', shape: 'dot', text: `calcul ${data.meta.ms} ms (${data.meta.lignes} lignes, ${data.meta.tickets} tickets)` });
      return [reply({ type: 'data', data }), null, null];
    }
    case 'fiche': {
      if (!M) return [reply({ type: 'nodata', etat: etat() }), null, null];
      if (!['article', 'client'].includes(p.kind) || !p.code) return null;
      return [reply({ type: 'fiche', kind: p.kind, code: String(p.code), data: TJE.fiche(M, p.filtres, p.kind, String(p.code), { today }) }), null, null];
    }
