const ST = {
  head: { font: { name: 'Arial', size: 10, bold: true, color: { argb: 'FFFFFFFF' } }, fill: { type: 'pattern', pattern: 'solid', fgColor: { argb: ARGB('#2F5D3A') } }, border: BORDER, alignment: { vertical: 'middle', wrapText: true } },
  titre: { font: { name: 'Arial', size: 12, bold: true, color: { argb: ARGB('#1E3A25') } } },
