function text(S, t, style) { put(S, S.r, 1, t, style); S.r++; }

// tableau générique : cols [{k,t,f}], rows [{}]
function table(S, cols, rows, o = {}) {
  if (o.title) { text(S, o.title, ST.soustitre); }
  const r0 = S.r;
  cols.forEach((c, i) => { put(S, S.r, i + 1, c.t, ST.head); width(S, i + 1, String(c.t).length); });
  S.r++;
  rows.forEach((row, j) => {
    const z = j % 2 === 1, bold = !!row.total;
    cols.forEach((c, i) => { const v = val(row[c.k], c.f); put(S, S.r, i + 1, v, st(c.f, z, bold)); width(S, i + 1, dispLen(v, c.f)); });
