function kpiRows(b) {
  return b.items.map(it => {
    const pctLike = it.f === 'pct';
    let vr = null, vf = 'pct';
    if (it.p !== null && it.p !== undefined && it.v !== null && it.v !== undefined) {
      if (pctLike) { vr = (it.v - it.p) * 100; vf = 'pts'; } else if (it.p) vr = (it.v - it.p) / Math.abs(it.p);
