function kpiTable(S, b, hasCmp) {
  if (b.title) text(S, b.title, ST.soustitre);
  const cols = ['Indicateur', 'Valeur'].concat(hasCmp ? ['Période de comparaison', 'Variation'] : [], ['Détail']);
  const r0 = S.r;
  cols.forEach((t, i) => { put(S, S.r, i + 1, t, ST.head); width(S, i + 1, t.length); });
  S.r++;
  kpiRows(b).forEach((x, j) => {
    const z = j % 2 === 1; let c = 1;
    put(S, S.r, c, x.l, st('txt', z)); width(S, c++, x.l.length);
    const vv = val(x.v, x.f); put(S, S.r, c, vv, st(x.f, z)); width(S, c++, dispLen(vv, x.f));
    if (hasCmp) {
      const pv = val(x.p, x.f); put(S, S.r, c, pv, st(x.f, z)); width(S, c++, dispLen(pv, x.f));
      put(S, S.r, c, x.vr === null ? null : x.vf === 'pts' ? Math.round(x.vr * 10) / 10 : x.vr, st(x.vf, z)); width(S, c++, 10);
