    S0.r++;
    blocks(S0, data.tabs.vue, hasCmp);
    finish(S0);

    const map = [['Articles', 'articles'], ['Clients', 'clients'], ['Plateformes', 'plateformes'], ['Journalier', 'temps'], ['Comptoir', 'comptoir'], ['Contrôle', 'controle'], ['Lignes', 'lignes']];
    for (const [nom, k] of map) {
      const S = newSheet(wb, nom);
      blocks(S, data.tabs[k] || [], hasCmp);
      finish(S);
    }
